/* Déclic — Physique : relativité générale */
(()=>{
const G=6.67e-11, C=3e8, MS=1.99e30, ME=5.97e24, RE=6.37e6, g=9.81;
const SUP='⁰¹²³⁴⁵⁶⁷⁸⁹';
const sup=n=>(n<0?'⁻':'')+String(Math.abs(Math.round(n))).split('').map(d=>SUP[+d]).join('');
// notation scientifique française : sci(2.45e-15) → 2,45·10⁻¹⁵
const sci=(v,d=2)=>{ if(!isFinite(v)) return '…'; if(v===0) return '0'; let e=Math.floor(Math.log10(Math.abs(v))), m=v/10**e; if(Math.abs(Math.round(m*10**d)/10**d)>=10){ m/=10; e++; } return fmt(m,d)+'·10'+sup(e); };
// flèche étiquetée
const vec=(P,x1,y1,x2,y2,c,l,q={})=>{ P.arrow(x1,y1,x2,y2,Object.assign({c,w:2.5,hs:10},q)); if(l&&Math.hypot(x2-x1,y2-y1)>1e-6) P.text(x2,y2,l,{c,dx:q.dx??6,dy:q.dy??-6}); return P; };
// rayon de Schwarzschild
const rs=M=>2*G*M/C**2;

COURS.push(
/* ================= 1. PRINCIPE D’ÉQUIVALENCE ================= */
{subj:'phy', sem:'rel', id:'phy-rg-equivalence', h:'Le principe d’équivalence', p:'Chute libre et absence de gravité sont la même chose : la lumière tombe, les horloges d’altitude avancent, et le GPS doit en tenir compte.', steps:[
 {h:'Deux masses qui n’ont rien à voir',p:`<p>Dans la mécanique de Newton, la lettre <i>m</i> joue deux rôles très différents. Dans <i>F</i> = <i>m a</i>, elle mesure la <b>résistance</b> d’un corps au changement de vitesse : plus <i>m</i> est grand, plus il faut pousser fort pour l’accélérer. Dans <i>F</i> = <i>G M m</i>/<i>r</i>², elle mesure la <b>sensibilité</b> du corps à la gravitation : c’est une « charge » gravitationnelle, comme la charge électrique l’est pour la force de Coulomb.</p>
<div class="def"><p>La <b>masse inerte</b> <i>m</i><sub>i</sub> est celle de <i>F</i> = <i>m</i><sub>i</sub> <i>a</i>. La <b>masse grave</b> <i>m</i><sub>g</sub> est celle du poids <i>P</i> = <i>m</i><sub>g</sub> <i>g</i>. Rien, dans la théorie de Newton, n’oblige ces deux nombres à être égaux.</p></div>
<div class="idea"><p>Pourtant, en chute libre, <i>m</i><sub>i</sub> <i>a</i> = <i>m</i><sub>g</sub> <i>g</i> donne <i>a</i> = (<i>m</i><sub>g</sub>/<i>m</i><sub>i</sub>) <i>g</i>. Si le rapport changeait d’un corps à l’autre, une bille de plomb et une bille de bois ne tomberaient pas ensemble. Or elles tombent ensemble, dans le vide, avec une précision extraordinaire.</p></div>
<div class="ex"><p>L’expérience de la balance de torsion d’Eötvös (vers 1900), reprise ensuite avec des pendules de torsion et des satellites, compare l’accélération de deux matériaux différents dans le même champ. Résultat : le rapport <i>m</i><sub>g</sub>/<i>m</i><sub>i</sub> est le même pour tous les corps à mieux que 10⁻¹⁴ près. On choisit donc les unités pour que <i>m</i><sub>g</sub> = <i>m</i><sub>i</sub>.</p></div>
<div class="warn"><p>Pour la force électrique, l’analogue est faux : un proton et un électron ont la même charge (au signe près) et des masses très différentes, donc des accélérations très différentes. La gravitation est la seule force qui « oublie » de quoi le corps est fait.</p></div>`,
  note:'Einstein a vu dans cette égalité, que Newton traitait comme une coïncidence, le point de départ d’une nouvelle théorie de la gravitation.'},
 {h:'L’ascenseur d’Einstein',p:`<p>Imagine un ascenseur fermé, sans fenêtre, dont le câble vient de casser. Tout tombe avec la même accélération <i>g</i> : la cabine, toi, la pomme que tu tiens. Si tu lâches la pomme, elle reste <b>immobile</b> devant toi. Si tu la lances, elle part en ligne droite à vitesse constante. Aucune expérience de mécanique faite à l’intérieur ne permet de savoir si tu tombes vers la Terre ou si tu flottes dans l’espace vide, loin de toute étoile.</p>
<div class="idea"><p>Inverse la situation. Une fusée, loin de toute masse, accélère à <i>a</i> = 9,81 m/s². Une pomme lâchée dans la cabine garde sa vitesse pendant que le plancher la rattrape : vue de l’intérieur, elle « tombe » vers le sol avec l’accélération <i>a</i>. Un passager sent son poids, un pendule oscille, l’eau reste au fond du verre. Rien ne distingue cette cabine d’une pièce posée sur la Terre.</p></div>
<div class="why"><p>Ces deux conclusions reposent sur l’égalité des masses inerte et grave. Si la pomme et la cabine n’avaient pas exactement la même accélération de chute, la pomme dériverait lentement et trahirait la gravité. C’est l’égalité <i>m</i><sub>g</sub> = <i>m</i><sub>i</sub> qui permet d’effacer complètement la gravitation dans un référentiel en chute libre.</p></div>
<div class="ex"><p>Les astronautes de la station spatiale ne sont pas « hors de la gravité » : à 400 km d’altitude, <i>g</i> vaut encore 8,7 m/s². Ils flottent parce que la station et eux tombent ensemble, en permanence, autour de la Terre.</p></div>`,
  fig:(()=>{ const P=plane({x:[-0.5,10.5],y:[-1.2,5.2],grid:false,axes:false,w:320});
    // cabine en chute libre
    P.rect(0.5,0.3,3.2,3.6,{fill:'var(--surface)',fo:1,c:'var(--ink)',w:2}); P.dot(2.1,2.3,{c:'var(--spark)',r:7}); P.text(2.1,2.3,'pomme immobile',{a:'middle',dy:-14,s:11,c:'var(--muted)'});
    vec(P,2.1,-0.1,2.1,-1.0,'var(--bad)','g',{dx:8,dy:4}); P.text(2.1,4.1,'chute libre',{a:'middle',dy:-6,s:12});
    // fusée accélérée
    P.rect(6.3,0.3,3.2,3.6,{fill:'var(--surface)',fo:1,c:'var(--ink)',w:2}); P.poly([[6.3,3.9],[7.9,5.0],[9.5,3.9]],{fill:'var(--line)',fo:.8,c:'var(--ink)',w:2});
    P.dot(7.9,0.55,{c:'var(--spark)',r:7}); P.text(7.9,0.55,'pomme au sol',{a:'middle',dy:-14,s:11,c:'var(--muted)'});
    vec(P,7.9,-0.1,7.9,-1.0,'var(--accent)','',{}); P.text(8.1,-0.9,'gaz',{s:11,c:'var(--muted)'}); vec(P,10.1,1.2,10.1,2.6,'var(--accent)','a',{dx:4,dy:-2}); P.text(7.9,4.6,'',{a:'middle'}); P.text(5.05,2.1,'=',{a:'middle',s:22,c:'var(--muted)'});
    return P.svg(); })(),
  note:'À gauche, la cabine tombe : la gravité a disparu à l’intérieur. À droite, la fusée accélère dans le vide : une gravité est apparue à l’intérieur. Les deux cabines sont indiscernables de l’intérieur.'},
 {h:'Le principe d’équivalence',p:`<p>L’expérience de pensée de l’ascenseur devient un principe fondateur, qu’Einstein a appelé « l’idée la plus heureuse de sa vie ».</p>
<div class="thm"><p><b>Principe d’équivalence.</b> Dans une région assez petite de l’espace et pendant une durée assez courte, un référentiel en chute libre est équivalent à un référentiel inertiel sans gravitation. Réciproquement, un référentiel uniformément accéléré d’accélération <i>a</i> est équivalent à un référentiel au repos dans un champ de gravité <i>g</i> = −<i>a</i>. Aucune expérience, de mécanique ou d’optique, ne peut les distinguer.</p></div>
<div class="idea"><p>Le mot nouveau par rapport à l’ascenseur est <b>aucune expérience</b>. Newton garantissait déjà l’équivalence pour les mouvements des masses. Einstein l’étend à toute la physique, en particulier à la lumière et aux horloges. C’est là que les prédictions nouvelles apparaissent : si la gravité est indiscernable d’une accélération, tout ce qu’une accélération fait à la lumière et au temps, la gravité le fait aussi.</p></div>
<div class="warn"><p>Le principe est <b>local</b>. Dans une grande cabine, la gravité terrestre n’est pas uniforme : elle pointe vers le centre de la Terre et faiblit avec l’altitude. Deux pommes lâchées aux deux bouts se rapprochent lentement, et une pomme en haut tombe un peu moins vite qu’une pomme en bas. Ces effets différentiels, qu’on appelle <b>forces de marée</b>, ne s’effacent pas et signalent la présence d’une vraie masse. On y reviendra avec les trous noirs.</p></div>
<div class="ex"><p>Dans une cabine de 3 m qui tombe près de la Terre, la différence d’accélération entre le haut et le bas vaut environ 2<i>g h</i>/<i>R</i> ≈ 2 × 9,81 × 3/(6,37·10⁶) ≈ 9·10⁻⁶ m/s². Pendant une chute de 10 s, les deux pommes se décalent de ½ × 9·10⁻⁶ × 100 ≈ 0,5 mm : « assez petit » signifie qu’on néglige ce genre d’écart.</p></div>`},
 {h:'Dans la cabine qui tombe',p:'Une cabine tombe en chute libre près de la Terre (air négligé). Une passagère lance une bille horizontalement à 2 m/s vers la paroi d’en face, située à 1 m. Vue de l’intérieur de la cabine, la bille…',
  opts:['décrit une parabole et touche la paroi 1,2 m plus bas','va tout droit à 2 m/s et touche la paroi à la hauteur du lancer','monte, car la cabine tombe plus vite qu’elle','ralentit, puisque la gravité la freine'],ans:1,
  why:'Dans un référentiel en chute libre, la gravité est effacée : la bille, la passagère et la cabine ont la même accélération. Vue de l’intérieur, la bille suit une droite à vitesse constante et met 0,5 s à traverser. Vue du sol, bille et cabine décrivent la même parabole de chute.'},
 {h:'La lumière tombe',p:`<p>Première conséquence du principe d’équivalence. Dans la fusée qui accélère à <i>a</i>, un rayon laser part horizontalement d’une paroi vers la paroi opposée, distante de <i>L</i>. Pour un observateur extérieur, inertiel, la lumière va tout droit. Pendant le temps de traversée <i>t</i> = <i>L</i>/<i>c</i>, le plancher est monté de ½<i>a t</i>². Vu de l’intérieur, le rayon arrive donc plus bas que son point de départ : il a <b>courbé vers le sol</b>.</p>
<div class="prop"><p>Dans la cabine accélérée, et donc dans un champ de gravité <i>g</i> = <i>a</i>, un rayon horizontal qui parcourt une distance <i>L</i> descend de <b><i>δ</i> = ½ <i>g</i> (<i>L</i>/<i>c</i>)² = <i>g L</i>²/(2<i>c</i>²)</b>.</p></div>
<div class="why"><p>Le principe d’équivalence impose la conclusion : si la gravité ne courbait pas la lumière, un rayon laser permettrait de distinguer la fusée accélérée d’une pièce posée sur Terre, ce que le principe interdit. La lumière n’a pas de masse, mais elle « tombe » quand même, parce que la gravité agit sur tout ce qui se déplace, pas sur une masse.</p></div>
<div class="ex"><p>Pour <i>L</i> = 3 m et <i>g</i> = 9,81 m/s² : <i>t</i> = 10⁻⁸ s et <i>δ</i> = ½ × 9,81 × 10⁻¹⁶ ≈ 4,9·10⁻¹⁶ m, moins d’un millième de la taille d’un proton. Sur Terre, l’effet est inobservable. Il devient mesurable quand la lumière frôle une étoile sur des millions de kilomètres (chapitre suivant).</p></div>
<p>Dans la figure, l’axe vertical est gradué en 10⁻¹⁶ m, sinon la courbe serait une droite parfaite.</p>`,
  params:[{id:'a',l:'Accélération a',min:0,max:30,step:1,v:10,u:' m/s²'},{id:'L',l:'Largeur L',min:1,max:5,step:.5,v:3,u:' m'}],
  draw:v=>{ const P=plane({x:[-0.6,5.4],y:[-46,6],grid:true,step:5,lab:10,w:320,h:220}); const k=v.a/18; // chute en 10⁻¹⁶ m : a·x²/(2c²)·1e16 = a x²/18
    P.rect(0,-45,v.L,50,{fill:'var(--line)',fo:.35,c:'var(--muted)',w:1.5}); P.seg(0,0,v.L,0,{c:'var(--muted)',w:1,dash:true});
    P.fn(x=>-k*x*x,{from:0,to:v.L,c:'var(--spark)',w:3.5}); P.dot(0,0,{c:'var(--spark)',r:5}); P.dot(v.L,-k*v.L*v.L,{c:'var(--spark)',r:5});
    vec(P,v.L+0.3,-20,v.L+0.3,-20+v.a*0.6,'var(--accent)','a',{dx:6,dy:0}); P.text(0.1,-42,'10⁻¹⁶ m',{s:11,c:'var(--muted)'}); return P.svg(); },
  info:v=>`Temps de traversée <i>t</i> = <i>L</i>/<i>c</i> = ${sci(v.L/C)} s · chute <i>δ</i> = ½<i>a t</i>² = ${sci(0.5*v.a*(v.L/C)**2)} m`,
  note:'La courbe est une parabole, comme pour une pierre lancée horizontalement : la lumière est simplement une « pierre » qui va très vite, donc qui a très peu de temps pour tomber.'},
 {h:'Le laser dans le hall',p:'Un rayon laser traverse horizontalement un hall de 30 m de large, à la surface de la Terre (<i>g</i> = 9,81 m/s², <i>c</i> = 3,00·10⁸ m/s). De combien descend-il pendant la traversée&nbsp;? Donne la réponse en unités de 10⁻¹⁴ m, arrondie au centième.',lab:'δ =',unit:'× 10⁻¹⁴ m',ans:4.905,tol:.011,
  why:'t = L/c = 30/(3·10⁸) = 10⁻⁷ s, puis δ = ½gt² = ½ × 9,81 × 10⁻¹⁴ = 4,905·10⁻¹⁴ m. Dix fois plus large, donc cent fois plus de chute qu’avec 3 m.'},
 {h:'Le temps dépend de l’altitude',p:`<p>Deuxième conséquence, plus surprenante. Reprends la fusée qui accélère à <i>a</i>, de hauteur <i>h</i>. Au plancher, un émetteur envoie une onde de fréquence <i>f</i> vers le plafond. La lumière met <i>t</i> = <i>h</i>/<i>c</i> à monter. Pendant ce temps, la fusée a gagné la vitesse <i>v</i> = <i>a t</i> = <i>a h</i>/<i>c</i> : le récepteur du plafond <b>s’éloigne</b> de l’onde qu’il reçoit.</p>
<div class="blk" data-t="Rappel"><p>Effet Doppler (relativité restreinte) : si le récepteur s’éloigne de la source à la vitesse <i>v</i> ≪ <i>c</i>, la fréquence reçue est <i>f</i>′ ≈ <i>f</i>(1 − <i>v</i>/<i>c</i>). Le signal est décalé vers le rouge.</p></div>
<div class="why"><p>En reportant <i>v</i> = <i>a h</i>/<i>c</i> : <i>f</i>′ = <i>f</i>(1 − <i>a h</i>/<i>c</i>²). Le principe d’équivalence dit que la même chose se produit dans une tour posée sur Terre, avec <i>a</i> = <i>g</i>. Or, dans la tour, rien ne bouge : si le récepteur compte moins d’oscillations par seconde que l’émetteur n’en produit, c’est que sa seconde est plus courte. <b>Une horloge en haut avance plus vite qu’une horloge en bas.</b></p></div>
<div class="prop"><p><b>Décalage gravitationnel.</b> Entre deux points séparés d’une hauteur <i>h</i> dans un champ <i>g</i> uniforme, la lumière qui monte perd la fraction <i>Δf</i>/<i>f</i> = <i>g h</i>/<i>c</i>² de sa fréquence, et les horloges diffèrent dans le même rapport : <b><i>Δt</i>/<i>t</i> = <i>g h</i>/<i>c</i>²</b>. La lumière qui descend est décalée vers le bleu.</p></div>
<div class="ex"><p>Entre le sol et le sommet d’une tour de 100 m, <i>g h</i>/<i>c</i>² = 9,81 × 100/(9·10¹⁶) ≈ 1,1·10⁻¹⁴. L’horloge du haut gagne 1,1·10⁻¹⁴ seconde par seconde, soit presque une nanoseconde par jour.</p></div>`,
  note:'Le décalage vers le rouge gravitationnel n’est pas un effet Doppler déguisé : dans la tour, source et récepteur sont immobiles. C’est le temps lui-même qui s’écoule à des rythmes différents selon l’altitude.'},
 {kind:'Méthode',h:'Calculer un décalage gravitationnel et une dérive d’horloge',p:`<p><b>Quand</b> : deux horloges ou un émetteur et un récepteur sont à des altitudes différentes, proches de la surface d’une planète (<i>h</i> petit devant le rayon, donc <i>g</i> constant), et on demande un décalage de fréquence ou l’avance d’une horloge sur l’autre.</p><p><b>Pourquoi</b> : le principe d’équivalence donne <i>Δf</i>/<i>f</i> = <i>Δt</i>/<i>t</i> = <i>g h</i>/<i>c</i>², une fraction sans unité, toujours minuscule.</p><p><b>Comment</b> : 1. Calcule la fraction <i>ε</i> = <i>g h</i>/<i>c</i>² en unités SI. 2. Pour une fréquence, <i>Δf</i> = <i>ε f</i> ; le signal qui monte est reçu plus bas en fréquence. 3. Pour une horloge, l’avance accumulée pendant une durée <i>T</i> vaut <i>ε T</i> : l’horloge du haut avance. 4. Choisis une unité lisible (ns par jour : 1 jour = 86 400 s).</p>`,
  demo:{enonce:'a) Un rayon gamma monte de 22,5 m dans une tour (expérience de Pound et Rebka). Quelle fraction de sa fréquence perd-il&nbsp;? b) Une horloge atomique est posée à 1000 m d’altitude, une autre au niveau de la mer. Combien gagne la première en un jour&nbsp;?',
   etapes:[
    {f:'<i>ε</i> = <i>g h</i>/<i>c</i>² = 9,81 × 22,5/(3,00·10⁸)² = 220,7/(9,00·10¹⁶) ≈ 2,45·10⁻¹⁵',w:'Tout en SI. La fraction est sans unité : m/s² × m / (m/s)² se simplifie.'},
    {f:'Le photon arrive avec <i>f</i>′ = <i>f</i>(1 − 2,45·10⁻¹⁵) : il a perdu 2,45·10⁻¹⁵ de sa fréquence',w:'Il monte, donc il perd de l’énergie, comme une pierre qui monte perd de la vitesse.'},
    {f:'<i>ε</i> = 9,81 × 1000/(9,00·10¹⁶) ≈ 1,09·10⁻¹³',w:'Même formule, avec <i>h</i> = 1000 m.'},
    {f:'Avance en un jour : <i>ε</i> × 86 400 ≈ 9,4·10⁻⁹ s = 9,4 ns',w:'La fraction multipliée par la durée donne le décalage accumulé. L’horloge d’altitude est en avance.'},
   ],
   conclusion:'2,45·10⁻¹⁵ pour la tour, 9,4 ns par jour pour l’horloge en altitude. Ces nombres sont minuscules, mais les horloges atomiques actuelles sont stables à 10⁻¹⁸ : elles détectent une différence d’altitude de quelques centimètres.'},
  note:'Retiens l’ordre de grandeur : près de la Terre, <i>g</i>/<i>c</i>² ≈ 1,1·10⁻¹⁶ par mètre, soit environ 9,4 ns par jour et par kilomètre.'},
 {h:'Au sommet de la tour',p:'Une horloge est installée au sommet d’une tour de 828 m, une autre identique à sa base (<i>g</i> = 9,81 m/s², <i>c</i> = 3,00·10⁸ m/s). Combien de nanosecondes l’horloge du sommet gagne-t-elle par jour&nbsp;? Arrondis au dixième.',lab:'Δt =',unit:'ns/jour',ans:7.8,tol:.06,
  why:'ε = gh/c² = 9,81 × 828/(9·10¹⁶) ≈ 9,03·10⁻¹⁴, puis 9,03·10⁻¹⁴ × 86 400 ≈ 7,8·10⁻⁹ s = 7,8 ns par jour.'},
 {h:'Régler l’altitude',p:'Deux horloges identiques sont posées, l’une au niveau de la mer, l’autre à l’altitude <i>h</i>. Règle <i>h</i> pour que l’horloge d’altitude gagne 10 ns par jour (à 0,3 ns près).',
  params:[{id:'h',l:'Altitude h',min:0,max:3000,step:50,v:500,u:' m'}],
  draw:v=>{ const P=plane({x:[-200,3200],y:[-3,32],grid:true,step:500,lab:1000,w:320,h:200}); const k=g/C**2*86400e9;
    P.fn(x=>k*x,{from:0,to:3000,c:'var(--accent)'}); P.seg(0,10,3000,10,{c:'var(--spark)',w:2,dash:true}); P.text(2950,10,'10 ns/jour',{a:'end',dy:-6,s:11,c:'var(--muted)'});
    P.dot(v.h,k*v.h,{l:fmt(k*v.h,1)+' ns'}); P.text(3100,-0.5,'h (m)',{a:'end',dy:14,s:11,c:'var(--muted)'}); return P.svg(); },
  info:v=>`<i>ε</i> = <i>g h</i>/<i>c</i>² = ${sci(g*v.h/C**2)} · avance par jour : ${fmt(g*v.h/C**2*86400e9,2)} ns`,
  ok:v=>Math.abs(g*v.h/C**2*86400e9-10)<.3,
  why:'Il faut ε × 86 400 = 10⁻⁸ s, donc h = 10⁻⁸ × c²/(g × 86 400) = 10⁻⁸ × 9·10¹⁶/(9,81 × 86 400) ≈ 1062 m. Sur la grille, h = 1050 m donne 9,9 ns par jour.'},
 {h:'L’expérience de Pound et Rebka',p:`<p>En 1959, Robert Pound et Glen Rebka mesurent pour la première fois le décalage gravitationnel sur Terre, dans une tour de 22,5 m de l’université où ils travaillent. Le défi : détecter une variation de fréquence de 2,45·10⁻¹⁵, cent mille fois plus fine que ce que les meilleurs spectromètres optiques résolvent alors.</p>
<div class="idea"><p>L’astuce vient de la physique nucléaire. Des noyaux de fer 57 émettent des rayons gamma d’une fréquence extrêmement bien définie, et d’autres noyaux de fer 57 ne les absorbent que si la fréquence est exactement la bonne (effet Mössbauer). Un rayon qui monte de 22,5 m arrive trop « rouge » pour être absorbé en haut : l’absorption diminue, et cette baisse se mesure.</p></div>
<div class="why"><p>Pour prouver que c’est bien un décalage de fréquence, ils compensent l’effet par un effet Doppler : en déplaçant la source vers le haut à la vitesse <i>v</i>, on redonne au photon la fraction <i>v</i>/<i>c</i> qu’il perd en montant. L’absorption redevient maximale pour <i>v</i>/<i>c</i> = <i>g h</i>/<i>c</i>², soit <i>v</i> = <i>g h</i>/<i>c</i> = 9,81 × 22,5/(3·10⁸) ≈ 7,4·10⁻⁷ m/s, moins d’un millimètre par heure. La mesure a confirmé la prédiction à 10 % près, puis à 1 % en 1964.</p></div>
<div class="ex"><p>Depuis, l’effet est vérifié avec des horloges embarquées dans des fusées (Gravity Probe A, 1976, à 10⁻⁴ près) et, en 2010, entre deux horloges optiques décalées de 33 cm seulement dans un laboratoire. En 2020, deux horloges séparées de 450 m dans une tour de Tokyo ont mesuré le décalage gravitationnel à mieux que 1 % près.</p></div>`},
 {h:'Le GPS : deux effets qui s’opposent',p:`<p>Chaque satellite GPS porte une horloge atomique et diffuse l’heure. Ton récepteur compare les heures reçues de plusieurs satellites : une erreur de 1 ns sur l’heure fait 30 cm d’erreur de distance, puisque la lumière parcourt 30 cm en une nanoseconde. Or deux effets relativistes décalent l’horloge du satellite par rapport à une horloge au sol.</p>
<div class="blk" data-t="Rappel"><p>Relativité restreinte : une horloge qui se déplace à la vitesse <i>v</i> retarde du facteur <i>γ</i> = 1/√(1 − <i>v</i>²/<i>c</i>²). Pour <i>v</i> ≪ <i>c</i>, <i>γ</i> − 1 ≈ <i>v</i>²/(2<i>c</i>²).</p></div>
<div class="idea"><p>Effet 1, la vitesse : le satellite file à 3,87 km/s, son horloge <b>retarde</b> de <i>v</i>²/(2<i>c</i>²) par seconde. Effet 2, l’altitude : à 20 200 km, il est beaucoup plus haut dans le champ de gravité, son horloge <b>avance</b>. Mais <i>g</i> n’est plus constant sur 20 000 km : la formule <i>g h</i>/<i>c</i>² doit être corrigée.</p></div>
<div class="why"><p>La fraction <i>g h</i>/<i>c</i>² est en fait la différence de potentiel gravitationnel (travail par unité de masse) divisée par <i>c</i>². Quand <i>g</i>(<i>r</i>) = <i>G M</i>/<i>r</i>² varie, on intègre : ∫<sub><i>R</i></sub><sup><i>r</i></sup> <i>G M</i>/<i>r</i>′² d<i>r</i>′ = <i>G M</i>(1/<i>R</i> − 1/<i>r</i>). D’où la formule générale <b><i>Δt</i>/<i>t</i> = (<i>G M</i>/<i>c</i>²)(1/<i>R</i> − 1/<i>r</i>)</b>, qui redonne <i>g h</i>/<i>c</i>² quand <i>r</i> = <i>R</i> + <i>h</i> avec <i>h</i> ≪ <i>R</i>.</p></div>
<div class="warn"><p>Si on appliquait naïvement <i>g h</i>/<i>c</i>² avec <i>h</i> = 20 200 km, on trouverait 190 µs par jour, quatre fois trop : le champ faiblit avec l’altitude, et la plus grande part du décalage se gagne dans les premiers milliers de kilomètres.</p></div>`,
  fig:(()=>{ const P=plane({x:[-5,5],y:[-4.6,4.6],grid:false,axes:false,w:300}); P.circ(0,0,1.5,{fill:'var(--sci)',fo:.35,c:'var(--sci)',w:2}); P.text(0,0,'Terre',{a:'middle',dy:4,s:12});
    P.circ(0,0,4.1,{c:'var(--muted)',w:1.5,dash:true}); const a=rad(40), x=4.1*Math.cos(a), y=4.1*Math.sin(a); P.dot(x,y,{c:'var(--accent)',l:'satellite'}); vec(P,x,y,x-1.1*Math.sin(a),y+1.1*Math.cos(a),'var(--accent)','v',{dx:-16,dy:-8});
    P.seg(0,0,1.5*Math.cos(rad(200)),1.5*Math.sin(rad(200)),{c:'var(--ink)',w:1}).text(0.75*Math.cos(rad(200)),0.75*Math.sin(rad(200)),'R',{dx:-14,dy:14,s:12});
    P.seg(0,0,x,y,{c:'var(--ink)',w:1,dash:true}).text(x/2,y/2,'r = 26 570 km',{dx:8,dy:14,s:11,c:'var(--muted)'}); P.text(-4.9,-4.1,'pas à l’échelle',{s:11,c:'var(--muted)'}); return P.svg(); })()},
 {kind:'Méthode',h:'Chiffrer les effets relativistes sur une horloge en orbite',p:`<p><b>Quand</b> : une horloge est en orbite circulaire (satellite, station) et on veut son décalage quotidien par rapport au sol, ou savoir lequel des deux effets l’emporte.</p><p><b>Pourquoi</b> : les deux effets sont du premier ordre et s’additionnent algébriquement. La vitesse fait retarder (−<i>v</i>²/(2<i>c</i>²)), l’altitude fait avancer (+(<i>G M</i>/<i>c</i>²)(1/<i>R</i> − 1/<i>r</i>)).</p><p><b>Comment</b> : 1. Rayon de l’orbite <i>r</i> = <i>R</i> + altitude. 2. Vitesse orbitale <i>v</i> = √(<i>G M</i>/<i>r</i>) (la gravitation fournit l’accélération centripète : <i>G M</i>/<i>r</i>² = <i>v</i>²/<i>r</i>). 3. Fraction cinématique <i>ε</i><sub>v</sub> = <i>v</i>²/(2<i>c</i>²), à retrancher. 4. Fraction gravitationnelle <i>ε</i><sub>g</sub> = (<i>G M</i>/<i>c</i>²)(1/<i>R</i> − 1/<i>r</i>), à ajouter. 5. Bilan <i>ε</i><sub>g</sub> − <i>ε</i><sub>v</sub>, multiplié par 86 400 s pour un jour.</p>`,
  demo:{enonce:'Un satellite GPS orbite à 20 200 km d’altitude (<i>G</i> = 6,67·10⁻¹¹, <i>M</i> = 5,97·10²⁴ kg, <i>R</i> = 6,37·10⁶ m, <i>c</i> = 3,00·10⁸ m/s). Calcule le décalage quotidien de son horloge par rapport au sol, effet par effet.',
   etapes:[
    {f:'<i>r</i> = 6,37·10⁶ + 2,02·10⁷ = 2,657·10⁷ m et <i>G M</i> = 3,98·10¹⁴ m³/s²',w:'On travaille avec le rayon depuis le centre de la Terre, pas avec l’altitude.'},
    {f:'<i>v</i> = √(<i>G M</i>/<i>r</i>) = √(3,98·10¹⁴/2,657·10⁷) ≈ 3,87·10³ m/s',w:'Orbite circulaire : la gravité joue le rôle de force centripète.'},
    {f:'<i>ε</i><sub>v</sub> = <i>v</i>²/(2<i>c</i>²) = 1,50·10⁷/(1,8·10¹⁷) ≈ 8,3·10⁻¹¹, soit −7,2 µs par jour',w:'8,3·10⁻¹¹ × 86 400 s = 7,2·10⁻⁶ s. L’horloge mobile retarde : signe moins.'},
    {f:'<i>ε</i><sub>g</sub> = (<i>G M</i>/<i>c</i>²)(1/<i>R</i> − 1/<i>r</i>) = 4,42·10⁻³ × (1,570·10⁻⁷ − 3,76·10⁻⁸) ≈ 5,28·10⁻¹⁰, soit +45,6 µs par jour',w:'<i>G M</i>/<i>c</i>² = 4,42·10⁻³ m est une longueur ; la parenthèse est en m⁻¹. L’horloge d’altitude avance : signe plus.'},
    {f:'Bilan : +45,6 − 7,2 ≈ +38 µs par jour',w:'La gravitation l’emporte largement : l’horloge du satellite avance sur celle du sol.'},
   ],
   conclusion:'Sans correction, l’heure diffusée dériverait de 38 µs par jour, et l’erreur de position de 38·10⁻⁶ × 3·10⁸ ≈ 11,5 km par jour. Les horloges des satellites sont donc réglées avant le lancement sur une fréquence légèrement plus basse (de 4,45·10⁻¹⁰ en valeur relative), pour qu’elles battent au bon rythme vu du sol.'}},
 {h:'La station spatiale',p:'La station spatiale internationale orbite à 400 km d’altitude (<i>G</i> = 6,67·10⁻¹¹, <i>M</i> = 5,97·10²⁴ kg, <i>R</i> = 6,37·10⁶ m, <i>c</i> = 3,00·10⁸ m/s). De combien de microsecondes par jour l’effet de la vitesse fait-il retarder son horloge&nbsp;? Arrondis au dixième.',lab:'retard =',unit:'µs/jour',ans:28.2,tol:.15,
  why:'r = 6,77·10⁶ m, v = √(GM/r) = √(3,98·10¹⁴/6,77·10⁶) ≈ 7,67·10³ m/s. ε<sub>v</sub> = v²/(2c²) = 5,88·10⁷/(1,8·10¹⁷) ≈ 3,27·10⁻¹⁰, soit 3,27·10⁻¹⁰ × 86 400 ≈ 28,2 µs par jour. Ici l’effet gravitationnel (+3,5 µs) est plus petit : contrairement au GPS, l’horloge de la station retarde.'},
 {kind:'Récapitulatif',h:'Ce qu’il faut retenir',p:`<div class="keep"><ul>
<li><b>Masse inerte</b> (<i>F</i> = <i>m</i><sub>i</sub><i>a</i>) et <b>masse grave</b> (<i>P</i> = <i>m</i><sub>g</sub><i>g</i>) sont égales à mieux que 10⁻¹⁴ près (Eötvös). Tous les corps tombent avec la même accélération.</li>
<li><b>Principe d’équivalence</b> : localement, chute libre = absence de gravité, et accélération <i>a</i> = gravité <i>g</i> = −<i>a</i>. Aucune expérience ne les distingue. Les forces de marée (gravité non uniforme) marquent la limite du « localement ».</li>
<li>La <b>lumière tombe</b> : sur une largeur <i>L</i>, elle descend de <i>δ</i> = <i>g L</i>²/(2<i>c</i>²), soit 4,9·10⁻¹⁶ m pour 3 m sur Terre.</li>
<li><b>Décalage gravitationnel</b> : <i>Δf</i>/<i>f</i> = <i>Δt</i>/<i>t</i> = <i>g h</i>/<i>c</i>² (champ uniforme). La lumière qui monte rougit, l’horloge du haut avance : 9,4 ns par jour et par kilomètre près de la Terre. Vérifié par Pound et Rebka (22,5 m, 2,45·10⁻¹⁵).</li>
<li>Quand <i>g</i> varie : <i>Δt</i>/<i>t</i> = (<i>G M</i>/<i>c</i>²)(1/<i>R</i> − 1/<i>r</i>).</li>
<li><b>Horloge en orbite</b> : vitesse → retard <i>v</i>²/(2<i>c</i>²), altitude → avance (<i>G M</i>/<i>c</i>²)(1/<i>R</i> − 1/<i>r</i>). GPS : −7 µs + 46 µs ≈ +38 µs par jour, soit 11,5 km d’erreur quotidienne sans correction. Station spatiale : la vitesse l’emporte, l’horloge retarde.</li>
</ul></div>
<p>Méthodes du chapitre : calculer un décalage gravitationnel près du sol (fraction <i>g h</i>/<i>c</i>², puis multiplier par la durée) et chiffrer les deux effets pour une horloge en orbite (vitesse orbitale par <i>v</i> = √(<i>G M</i>/<i>r</i>), puis bilan algébrique).</p>`},
 {kind:'Problème',h:'Les horloges de la tour de Tokyo',
  p:'En 2020, deux horloges optiques identiques ont été installées dans une tour de Tokyo, l’une au sol, l’autre 450 m plus haut, et comparées par fibre optique. Ces horloges sont stables à 10⁻¹⁸ en valeur relative. On prend <i>g</i> = 9,81 m/s² et <i>c</i> = 3,00·10⁸ m/s. On veut prédire ce que l’expérience doit mesurer et ce qu’une telle horloge permet de détecter.',
  parts:[
   {q:'a) Quelle fraction sépare les fréquences des deux horloges&nbsp;? Donne la réponse en unités de 10⁻¹⁴, arrondie au centième.',lab:'ε =',unit:'× 10⁻¹⁴',ans:4.905,tol:.011,hint:'C’est <i>g h</i>/<i>c</i>², avec <i>h</i> = 450 m.',why:'ε = gh/c² = 9,81 × 450/(9·10¹⁶) = 4414,5/(9·10¹⁶) ≈ 4,905·10⁻¹⁴.'},
   {q:'b) Combien l’horloge du haut gagne-t-elle par jour&nbsp;? Arrondis au centième de nanoseconde.',lab:'Δt =',unit:'ns/jour',ans:4.24,tol:.02,hint:'Multiplie la fraction par la durée d’un jour, 86 400 s.',why:'4,905·10⁻¹⁴ × 86 400 ≈ 4,24·10⁻⁹ s = 4,24 ns par jour.'},
   {q:'c) On fait descendre l’horloge du haut au rez-de-chaussée, à côté de l’autre. Que constate-t-on&nbsp;?',opts:['Elle reste en avance de ce qu’elle a accumulé, puis bat désormais au même rythme','Elle revient progressivement à l’heure de l’horloge du bas','Elle continue d’avancer de 4,24 ns par jour, car elle a « appris » le rythme d’altitude','Elle est en retard, car la descente l’a ralentie'],ans:0,hint:'Le rythme d’une horloge dépend de l’endroit où elle est, pas de son histoire.',why:'À la même altitude, les deux horloges battent au même rythme. L’avance accumulée pendant le séjour en hauteur reste acquise : le temps en altitude s’est réellement écoulé plus vite.'},
   {q:'d) Avec une stabilité de 10⁻¹⁸, quelle différence d’altitude minimale deux telles horloges peuvent-elles détecter&nbsp;? Arrondis au millimètre.',lab:'h =',unit:'mm',ans:9.17,tol:.05,hint:'Cherche <i>h</i> tel que <i>g h</i>/<i>c</i>² = 10⁻¹⁸.',why:'h = 10⁻¹⁸ × c²/g = 10⁻¹⁸ × 9·10¹⁶/9,81 ≈ 9,2·10⁻³ m : moins d’un centimètre.'},
  ],
  sol:'<p>Le décalage gravitationnel entre deux points séparés de <i>h</i> près du sol vaut ε = <i>gh</i>/<i>c</i>² = 9,81 × 450/(9·10¹⁶) ≈ 4,9·10⁻¹⁴ : l’horloge du haut bat plus vite dans ce rapport, et gagne 4,9·10⁻¹⁴ × 86 400 ≈ 4,24 ns chaque jour. L’expérience a trouvé cette valeur à mieux que 1 % près.</p><p>Le décalage est une propriété du lieu : redescendue, l’horloge bat à nouveau comme sa voisine, mais garde l’avance accumulée. Il n’y a pas de « rattrapage ».</p><p>Une stabilité de 10⁻¹⁸ correspond à <i>h</i> = 10⁻¹⁸<i>c</i>²/<i>g</i> ≈ 9 mm. Deux horloges optiques reliées par fibre mesurent donc une différence d’altitude au centimètre : c’est la géodésie relativiste, qui sert déjà à cartographier le champ de gravité terrestre.</p>'},
 {kind:'Problème',h:'Le temps des astronautes',
  p:'La station spatiale orbite à 400 km d’altitude sur une orbite circulaire. Un astronaute y reste 6 mois (183 jours). Données : <i>G</i> = 6,67·10⁻¹¹ m³/(kg·s²), <i>M</i> = 5,97·10²⁴ kg, <i>R</i> = 6,37·10⁶ m, <i>c</i> = 3,00·10⁸ m/s. On cherche s’il revient plus jeune ou plus vieux que s’il était resté au sol, et de combien.',
  parts:[
   {q:'a) Quelle est la vitesse orbitale de la station&nbsp;? Arrondis à 10 m/s.',lab:'v =',unit:'m/s',ans:7669,tol:12,hint:'Orbite circulaire : <i>G M</i>/<i>r</i>² = <i>v</i>²/<i>r</i>, avec <i>r</i> = <i>R</i> + 400 km.',why:'r = 6,77·10⁶ m et v = √(GM/r) = √(3,98·10¹⁴/6,77·10⁶) ≈ 7,67·10³ m/s, environ 27 600 km/h.'},
   {q:'b) De combien de microsecondes par jour l’effet de vitesse fait-il retarder l’horloge de bord&nbsp;? Arrondis au dixième.',lab:'retard =',unit:'µs/jour',ans:28.2,tol:.15,hint:'Fraction <i>v</i>²/(2<i>c</i>²), puis × 86 400 s.',why:'v²/(2c²) = 5,88·10⁷/(1,8·10¹⁷) ≈ 3,27·10⁻¹⁰, soit 28,2 µs par jour.'},
   {q:'c) De combien de microsecondes par jour l’altitude la fait-elle avancer&nbsp;? Arrondis au dixième.',lab:'avance =',unit:'µs/jour',ans:3.55,tol:.06,hint:'Utilise (<i>G M</i>/<i>c</i>²)(1/<i>R</i> − 1/<i>r</i>) : le champ varie peu sur 400 km, mais prends la formule exacte.',why:'GM/c² = 4,42·10⁻³ m et 1/R − 1/r = 1,570·10⁻⁷ − 1,477·10⁻⁷ = 9,28·10⁻⁹ m⁻¹ : ε<sub>g</sub> ≈ 4,10·10⁻¹¹, soit 3,5 µs par jour. (La formule gh/c² donnerait 3,8 µs : proche, mais déjà 7 % trop grand.)'},
   {q:'d) Au retour, l’astronaute est…',opts:['plus vieux de 24,7 µs par jour passé en orbite, soit 4,5 ms au total','plus jeune de 24,7 µs par jour passé en orbite, soit 4,5 ms au total','plus jeune de 31,8 µs par jour, les deux effets s’ajoutant','du même âge : les deux effets se compensent exactement en orbite'],ans:1,hint:'Fais le bilan algébrique : quel effet l’emporte, et dans quel sens&nbsp;?',why:'Bilan : +3,5 − 28,2 = −24,7 µs par jour. L’horloge de bord retarde, l’astronaute vieillit moins : 24,7 µs × 183 ≈ 4,5 ms en six mois. Le GPS, beaucoup plus haut et plus lent, a le bilan opposé.'},
  ],
  sol:'<p>Rayon de l’orbite <i>r</i> = 6,77·10⁶ m, vitesse <i>v</i> = √(<i>GM</i>/<i>r</i>) ≈ 7,67 km/s.</p><p>Effet de vitesse (relativité restreinte) : <i>v</i>²/(2<i>c</i>²) ≈ 3,27·10⁻¹⁰, donc l’horloge de bord retarde de 28,2 µs par jour. Effet d’altitude (relativité générale) : (<i>GM</i>/<i>c</i>²)(1/<i>R</i> − 1/<i>r</i>) ≈ 4,1·10⁻¹¹, donc elle avance de 3,5 µs par jour.</p><p>Le bilan est −24,7 µs par jour : en orbite basse, la vitesse l’emporte et l’astronaute revient plus jeune d’environ 4,5 ms après six mois. Les deux effets s’équilibrent pour une orbite où <i>v</i>²/2 = <i>GM</i>(1/<i>R</i> − 1/<i>r</i>), c’est-à-dire <i>GM</i>/(2<i>r</i>) = <i>GM</i>/<i>R</i> − <i>GM</i>/<i>r</i>, soit <i>r</i> = 3<i>R</i>/2 : vers 3200 km d’altitude. Au-dessus, comme pour le GPS, l’horloge en orbite avance.</p>'},
]},
/* ================= 2. ESPACE-TEMPS COURBE ================= */
{subj:'phy', sem:'rel', id:'phy-rg-courbure', h:'Espace-temps courbe et géodésiques', p:'La gravitation n’est plus une force mais une géométrie : la métrique de Schwarzschild, la déviation de la lumière par le Soleil et l’avance du périhélie de Mercure.', steps:[
 {h:'Pourquoi une force ne suffit plus',p:`<p>Le chapitre précédent a montré que la gravitation s’efface dans un référentiel en chute libre. Une vraie force ne fait pas ça : on ne peut pas annuler la force électrique sur une charge en choisissant un référentiel. La gravitation ressemble plutôt aux forces d’inertie, la force centrifuge dans un manège par exemple, qui apparaissent ou disparaissent selon le référentiel choisi.</p>
<div class="idea"><p>Autre indice : la gravitation agit sur tout de la même façon, y compris sur la lumière, qui n’a pas de masse. Ce qui agit sur tout, indépendamment de la composition, n’est pas une propriété des corps mais une propriété du <b>lieu</b>. L’idée d’Einstein : la gravitation est une déformation de l’espace-temps lui-même, et les corps « tombent » parce qu’ils suivent le chemin le plus naturel dans cet espace-temps déformé.</p></div>
<div class="why"><p>La loi de Newton pose aussi un problème de principe : <i>F</i> = <i>G M m</i>/<i>r</i>² agit instantanément à distance. Si le Soleil disparaissait, la Terre quitterait son orbite à l’instant même, alors que la relativité restreinte interdit à toute information de voyager plus vite que <i>c</i>. Une théorie relativiste de la gravitation doit propager ses effets à vitesse finie : ce seront les ondes gravitationnelles du dernier chapitre.</p></div>
<div class="ex"><p>Dans la gravitation newtonienne, la planète tourne parce qu’une force la tire vers le Soleil. En relativité générale, la planète ne subit <b>aucune force</b> : elle avance tout droit, à vitesse constante, dans un espace-temps que la masse du Soleil a courbé. C’est ce « tout droit » qu’il faut maintenant définir.</p></div>`},
 {h:'Géométrie sur une sphère',p:`<p>Pour comprendre un espace courbe, commence par une surface courbe que tu connais : la sphère. Sur un plan, la somme des angles d’un triangle vaut 180°, et deux droites parallèles ne se rencontrent jamais. Sur une sphère, ces deux règles tombent.</p>
<div class="def"><p>Une <b>géométrie courbe</b> est une géométrie où la somme des angles d’un triangle n’est pas 180°. L’écart <i>E</i> = (somme des angles) − 180° s’appelle l’<b>excès angulaire</b>. Sur une sphère de rayon <i>R</i>, il est proportionnel à l’aire du triangle : <b><i>E</i> = <i>A</i>/<i>R</i>²</b> (en radians).</p></div>
<div class="ex"><p>Prends le triangle formé par le pôle Nord et deux points de l’équateur séparés de 90° de longitude. Les deux méridiens coupent l’équateur à angle droit, et se coupent au pôle à 90° : trois angles droits, somme 270°, excès 90° = π/2. L’aire du triangle est un huitième de la sphère, 4π<i>R</i>²/8 = π<i>R</i>²/2, et <i>A</i>/<i>R</i>² = π/2. La formule est vérifiée.</p></div>
<div class="idea"><p>L’excès se mesure <b>de l’intérieur</b>, sans quitter la surface : un arpenteur qui ne voit pas la troisième dimension détecte la courbure en mesurant des angles. De même, nous mesurons la courbure de l’espace-temps sans « sortir » dans une dimension de plus. Un petit triangle (<i>A</i> ≪ <i>R</i>²) a un excès négligeable : localement, la sphère ressemble à un plan, comme la Terre nous semble plate. C’est l’analogue géométrique du « localement » du principe d’équivalence.</p></div>
<div class="warn"><p>Courbe ne veut pas dire « plongé dans un espace plus grand ». Un cylindre semble courbe, mais la somme des angles d’un triangle dessiné dessus vaut exactement 180° : on peut le dérouler à plat. Sa courbure, au sens qui nous intéresse, est nulle.</p></div>`,
  fig:(()=>{ const S=space({r:1.45,az:25,el:22,axes:false,w:300}); const P=S.P; const n=60;
    P.circ(0,0,1.0,{c:'var(--muted)',w:1.5}); // contour (approximation)
    const eq=[]; for(let i=0;i<=n;i++){ const t=2*Math.PI*i/n; eq.push([Math.cos(t),Math.sin(t),0]); } S.poly(eq,{open:true,c:'var(--line)',w:2});
    const mer=(lam,c)=>{ const pts=[]; for(let i=0;i<=n;i++){ const ph=Math.PI/2*i/n; pts.push([Math.cos(ph)*Math.cos(lam),Math.cos(ph)*Math.sin(lam),Math.sin(ph)]); } S.poly(pts,{open:true,c,w:3}); };
    const l1=rad(200), l2=rad(290); mer(l1,'var(--accent)'); mer(l2,'var(--accent)');
    const arc=[]; for(let i=0;i<=n;i++){ const t=l1+(l2-l1)*i/n; arc.push([Math.cos(t),Math.sin(t),0]); } S.poly(arc,{open:true,c:'var(--accent)',w:3});
    S.dot([0,0,1],{l:'pôle 90°',dx:8,dy:-6}); S.dot([Math.cos(l1),Math.sin(l1),0],{l:'90°',dx:-26,dy:16}); S.dot([Math.cos(l2),Math.sin(l2),0],{l:'90°',dx:6,dy:16});
    S.text([0,0,-1.25],'somme des angles : 270°',{a:'middle',s:12,c:'var(--muted)'}); return S.svg(); })(),
  note:'Le triangle « pôle, équateur, équateur » a trois angles droits. Son excès de 90° vient de son aire : un huitième de la sphère.'},
 {h:'L’excès d’un triangle terrestre',p:'Trois bornes géodésiques forment sur la Terre (<i>R</i> = 6,37·10⁶ m, supposée sphérique) un triangle d’aire 1,0·10⁶ km². De combien de degrés la somme de ses angles dépasse-t-elle 180°&nbsp;? Arrondis au centième de degré.',lab:'E =',unit:'°',ans:1.41,tol:.02,
  why:'E = A/R² = 10¹² m²/(6,37·10⁶ m)² = 10¹²/4,06·10¹³ ≈ 0,0246 rad. En degrés : 0,0246 × 180/π ≈ 1,41°. Gauss a cherché cet excès, en vain, sur un triangle de collines bien plus petit.'},
 {h:'La géodésique : le chemin le plus droit',p:`<p>Sur un plan, « aller tout droit » veut dire suivre une droite, qui est aussi le plus court chemin entre deux points. Sur une sphère, il n’y a pas de droite. Que fait un avion qui vole « tout droit », sans jamais tourner le manche&nbsp;?</p>
<div class="def"><p>Une <b>géodésique</b> est une courbe qui, à chaque instant, va tout droit dans la surface : elle ne tourne ni à gauche ni à droite. Entre deux points assez proches, c’est le plus court chemin. Sur une sphère, les géodésiques sont les <b>grands cercles</b>, les cercles de même rayon que la sphère (équateur, méridiens).</p></div>
<div class="idea"><p>Deux voyageurs partent de l’équateur, à quelques centaines de kilomètres l’un de l’autre, et marchent chacun plein nord, parfaitement droit. Ils ne tournent jamais. Pourtant la distance qui les sépare diminue, et ils se rencontrent au pôle. Un observateur qui croirait la Terre plate dirait qu’une force mystérieuse les attire l’un vers l’autre. Il n’y a aucune force : c’est la courbure qui rapproche deux chemins droits.</p></div>
<div class="why"><p>Transposé à l’espace-temps : deux pommes lâchées côte à côte se rapprochent en tombant vers le centre de la Terre. Newton dit « force de marée ». Einstein dit « deux géodésiques qui convergent dans un espace-temps courbe ». Les deux descriptions donnent les mêmes mouvements près de la Terre, mais la seconde ne demande aucune force et respecte le principe d’équivalence.</p></div>
<div class="ex"><p>Deux voyageurs partent de l’équateur séparés de <i>Δλ</i> = 20° de longitude, soit 2220 km. À la latitude <i>φ</i>, les méridiens sont distants de <i>d</i> = <i>R</i> <i>Δλ</i> cos <i>φ</i> : 1920 km à 30°, 1110 km à 60°, 0 au pôle. Déplace le curseur pour voir le rapprochement.</p></div>`,
  params:[{id:'phi',l:'Latitude φ',min:0,max:90,step:5,v:0,u:'°'}],
  draw:v=>{ const S=space({r:1.45,az:25,el:22,axes:false,w:300}); const P=S.P; const n=60; P.circ(0,0,1.0,{c:'var(--muted)',w:1.5});
    const eq=[]; for(let i=0;i<=n;i++){ const t=2*Math.PI*i/n; eq.push([Math.cos(t),Math.sin(t),0]); } S.poly(eq,{open:true,c:'var(--line)',w:2});
    const l1=rad(230), l2=rad(250), ph=rad(v.phi);
    const mer=(lam,c,to)=>{ const pts=[]; for(let i=0;i<=n;i++){ const p=to*i/n; pts.push([Math.cos(p)*Math.cos(lam),Math.cos(p)*Math.sin(lam),Math.sin(p)]); } S.poly(pts,{open:true,c,w:3}); };
    mer(l1,'var(--line)',Math.PI/2); mer(l2,'var(--line)',Math.PI/2); mer(l1,'var(--accent)',Math.max(ph,1e-3)); mer(l2,'var(--accent)',Math.max(ph,1e-3));
    const A=[Math.cos(ph)*Math.cos(l1),Math.cos(ph)*Math.sin(l1),Math.sin(ph)], B=[Math.cos(ph)*Math.cos(l2),Math.cos(ph)*Math.sin(l2),Math.sin(ph)];
    S.seg(A,B,{c:'var(--spark)',w:3}); S.dot(A,{c:'var(--spark)',r:5}); S.dot(B,{c:'var(--spark)',r:5}); S.dot([0,0,1],{l:'pôle',dx:8,dy:-6,r:4,c:'var(--muted)'});
    S.text([0,0,-1.25],'distance : '+fmt(RE*rad(20)*Math.cos(ph)/1000,0)+' km',{a:'middle',s:12}); return S.svg(); },
  info:v=>`<i>d</i> = <i>R</i> <i>Δλ</i> cos <i>φ</i> = 6370 × 0,349 × cos ${v.phi}° ≈ ${fmt(RE*rad(20)*Math.cos(rad(v.phi))/1000,0)} km. Les deux marcheurs vont « tout droit » et se rapprochent quand même.`},
 {h:'La matière courbe l’espace-temps',p:`<p>Voici le cœur de la relativité générale, en deux phrases : la matière et l’énergie <b>courbent</b> l’espace-temps autour d’elles ; les corps libres (planètes, pommes, photons) suivent les <b>géodésiques</b> de cet espace-temps courbe. La gravitation n’est plus une force ajoutée à la géométrie, elle est la géométrie.</p>
<div class="blk" data-t="Rappel"><p>En relativité restreinte, l’intervalle entre deux événements voisins, d<i>s</i>² = <i>c</i>²d<i>t</i>² − d<i>x</i>² − d<i>y</i>² − d<i>z</i>², est le même pour tous les observateurs. Pour une horloge, d<i>s</i> = <i>c</i> d<i>τ</i> mesure le temps propre écoulé.</p></div>
<div class="def"><p>Une <b>métrique</b> est la règle qui donne l’intervalle d<i>s</i>² entre deux événements voisins. Dans un espace-temps courbe, les coefficients devant d<i>t</i>², d<i>r</i>²… ne valent plus 1 : ils <b>dépendent du lieu</b>. Par exemple d<i>s</i>² = <i>A</i>(<i>r</i>) <i>c</i>²d<i>t</i>² − <i>B</i>(<i>r</i>) d<i>r</i>² − …, avec <i>A</i> et <i>B</i> fixés par la masse qui courbe l’espace-temps.</p></div>
<div class="idea"><p>Le coefficient <i>A</i>(<i>r</i>) dit comment le temps propre d’une horloge immobile en <i>r</i> est relié au temps <i>t</i> d’un observateur très éloigné : <i>c</i>²d<i>τ</i>² = <i>A</i>(<i>r</i>) <i>c</i>²d<i>t</i>², donc d<i>τ</i> = √<i>A</i> d<i>t</i>. Si <i>A</i> &lt; 1 près d’une masse, les horloges y battent plus lentement que loin : c’est exactement le décalage gravitationnel du chapitre précédent, lu dans la géométrie. Le coefficient <i>B</i> dit de même que les règles n’ont pas la même longueur partout.</p></div>
<div class="why"><p>Les équations d’Einstein relient les coefficients de la métrique à la répartition de masse et d’énergie. Elles sont trop lourdes pour ce cours ; mais leur solution la plus importante, pour une masse isolée et sphérique, tient en une ligne. C’est la prochaine étape.</p></div>`,
  note:'« La matière dit à l’espace-temps comment se courber ; l’espace-temps dit à la matière comment se déplacer. » Cette formule du physicien John Wheeler résume la théorie.'},
 {h:'La métrique de Schwarzschild',p:`<p>En 1916, quelques semaines après la publication des équations d’Einstein, Karl Schwarzschild en trouve la solution exacte autour d’une masse <i>M</i> sphérique, immobile et isolée (une étoile, une planète, un trou noir). En coordonnées sphériques (<i>r</i>, <i>θ</i>, <i>φ</i>) et pour un déplacement radial :</p>
<div class="thm"><p><b>d<i>s</i>² = (1 − <i>r</i><sub>s</sub>/<i>r</i>) <i>c</i>²d<i>t</i>² − d<i>r</i>²/(1 − <i>r</i><sub>s</sub>/<i>r</i>) − <i>r</i>²dΩ²</b>, avec <b><i>r</i><sub>s</sub> = 2<i>G M</i>/<i>c</i>²</b> le <b>rayon de Schwarzschild</b>. Le facteur clé est le coefficient temporel <b>1 − 2<i>G M</i>/(<i>r c</i>²)</b>.</p></div>
<div class="idea"><p>Lecture : <i>t</i> est le temps d’un observateur très éloigné, là où le facteur vaut 1. Une horloge immobile à la distance <i>r</i> a un temps propre d<i>τ</i> = √(1 − <i>r</i><sub>s</sub>/<i>r</i>) d<i>t</i> : elle bat plus lentement que l’horloge lointaine. Plus <i>r</i> est petit, plus le facteur s’éloigne de 1. Pour <i>r</i> = <i>r</i><sub>s</sub>, il s’annule : c’est l’horizon d’un trou noir (chapitre suivant). Loin de la masse, <i>r</i><sub>s</sub>/<i>r</i> ≪ 1 et on retrouve l’espace-temps plat de la relativité restreinte.</p></div>
<div class="ex"><p>Pour le Soleil, <i>r</i><sub>s</sub> = 2 × 6,67·10⁻¹¹ × 1,99·10³⁰/(9·10¹⁶) ≈ 2,95 km, à comparer au rayon du Soleil 6,96·10⁵ km : à la surface, <i>r</i><sub>s</sub>/<i>r</i> ≈ 4,2·10⁻⁶. Pour la Terre, <i>r</i><sub>s</sub> ≈ 8,9 mm et <i>r</i><sub>s</sub>/<i>R</i> ≈ 1,4·10⁻⁹. Dans le système solaire, l’espace-temps est presque plat : les écarts à Newton sont de l’ordre de <i>r</i><sub>s</sub>/<i>r</i>.</p></div>
<p>Dans la figure, le facteur est tracé en fonction de <i>r</i> pour une masse de quelques masses solaires : il n’est vraiment différent de 1 qu’à quelques <i>r</i><sub>s</sub>.</p>`,
  params:[{id:'M',l:'Masse M',min:1,max:20,step:1,v:5,u:' M☉'},{id:'r',l:'Distance r',min:10,max:300,step:10,v:100,u:' km'}],
  draw:v=>{ const RS=rs(v.M*MS)/1000; const P=plane({x:[-25,320],y:[-0.12,1.12],grid:true,step:50,lab:100,w:320,h:200}); P.text(-20,1.0,'1',{a:'end',dx:-2,dy:4,s:11,c:'var(--muted)'}).text(-20,0.5,'0,5',{a:'end',dx:-2,dy:4,s:11,c:'var(--muted)'});
    P.seg(0,1,320,1,{c:'var(--line)',w:1.5,dash:true}); P.fn(x=>x>RS*1.001?1-RS/x:NaN,{from:0,to:320,c:'var(--accent)',n:400}); P.seg(RS,0,RS,1,{c:'var(--bad)',w:2,dash:true}); P.text(RS,1.02,'rₛ = '+fmt(RS,1)+' km',{dx:4,dy:-2,s:11,c:'var(--bad)'});
    if(v.r>RS) P.dot(v.r,1-RS/v.r,{l:fmt(1-RS/v.r,3)}); else P.text(160,0.5,'r < rₛ : sous l’horizon',{a:'middle',c:'var(--bad)'});
    P.text(310,0,'r (km)',{a:'end',dy:16,s:11,c:'var(--muted)'}); return P.svg(); },
  info:v=>{ const RS=rs(v.M*MS); if(v.r*1000<=RS) return `<i>r</i><sub>s</sub> = ${fmt(RS/1000,1)} km : la distance choisie est sous l’horizon, le facteur n’a plus le sens d’un rythme d’horloge.`; const f=1-RS/(v.r*1000); return `<i>r</i><sub>s</sub> = ${fmt(RS/1000,1)} km · facteur 1 − <i>r</i><sub>s</sub>/<i>r</i> = ${fmt(f,4)} · une horloge en <i>r</i> bat à √(facteur) = ${fmt(Math.sqrt(f),4)} fois le rythme d’une horloge lointaine`; }},
 {kind:'Méthode',h:'Lire la métrique : le décalage gravitationnel exact',p:`<p><b>Quand</b> : une horloge ou une source lumineuse est immobile à la distance <i>r</i> d’une masse <i>M</i>, et on veut son rythme ou sa fréquence vus de loin, ou le rapport entre deux altitudes. Indispensable quand <i>r</i><sub>s</sub>/<i>r</i> n’est plus minuscule (étoiles à neutrons, trous noirs) ; sinon, l’approximation du chapitre précédent suffit.</p><p><b>Pourquoi</b> : d<i>τ</i> = √(1 − <i>r</i><sub>s</sub>/<i>r</i>) d<i>t</i>. La fréquence d’une onde est un nombre d’oscillations par unité de temps propre : émise à la fréquence <i>f</i><sub>e</sub> en <i>r</i>, elle est reçue à l’infini avec <b><i>f</i><sub>∞</sub> = <i>f</i><sub>e</sub> √(1 − <i>r</i><sub>s</sub>/<i>r</i>)</b>. Entre deux rayons <i>r</i>₁ &lt; <i>r</i>₂ : <i>f</i>₂/<i>f</i>₁ = √(1 − <i>r</i><sub>s</sub>/<i>r</i>₁)/√(1 − <i>r</i><sub>s</sub>/<i>r</i>₂).</p><p><b>Comment</b> : 1. Calcule <i>r</i><sub>s</sub> = 2<i>G M</i>/<i>c</i>². 2. Forme le facteur 1 − <i>r</i><sub>s</sub>/<i>r</i>, puis sa racine. 3. Le décalage vers le rouge est <i>z</i> = <i>λ</i><sub>∞</sub>/<i>λ</i><sub>e</sub> − 1 = 1/√(1 − <i>r</i><sub>s</sub>/<i>r</i>) − 1. 4. Compare à l’approximation <i>z</i> ≈ <i>G M</i>/(<i>r c</i>²) = <i>r</i><sub>s</sub>/(2<i>r</i>), qui est le développement au premier ordre.</p>`,
  demo:{enonce:'Une étoile à neutrons a une masse <i>M</i> = 1,4 masse solaire et un rayon <i>R</i> = 12 km (<i>G</i> = 6,67·10⁻¹¹, <i>M</i>☉ = 1,99·10³⁰ kg, <i>c</i> = 3,00·10⁸ m/s). Une raie émise à sa surface à <i>λ</i><sub>e</sub> = 500 nm est observée de loin. Calcule le décalage <i>z</i> exact, la longueur d’onde reçue, et compare à l’approximation.',
   etapes:[
    {f:'<i>r</i><sub>s</sub> = 2 × 6,67·10⁻¹¹ × 1,4 × 1,99·10³⁰/(9,00·10¹⁶) ≈ 4,13·10³ m = 4,13 km',w:'Le rayon de Schwarzschild d’abord : il donne l’échelle de tous les effets.'},
    {f:'1 − <i>r</i><sub>s</sub>/<i>R</i> = 1 − 4,13/12 ≈ 0,656, et √0,656 ≈ 0,810',w:'Ici <i>r</i><sub>s</sub>/<i>R</i> = 0,34 : on est loin du régime « presque plat ». Une horloge de surface bat à 81 % du rythme d’une horloge lointaine.'},
    {f:'<i>z</i> = 1/0,810 − 1 ≈ 0,235, donc <i>λ</i><sub>∞</sub> = 500 × 1,235 ≈ 617 nm',w:'La raie verte arrive orange : chaque longueur d’onde est étirée de 23,5 %.'},
    {f:'Approximation : <i>z</i> ≈ <i>r</i><sub>s</sub>/(2<i>R</i>) = 0,172',w:'Elle sous-estime l’effet de 27 %. Pour la Terre ou le Soleil, l’écart serait invisible (<i>r</i><sub>s</sub>/<i>r</i> &lt; 10⁻⁵).'},
   ],
   conclusion:'<i>z</i> = 0,235 exactement, 0,172 au premier ordre. Règle : tant que <i>r</i><sub>s</sub>/<i>r</i> &lt; 10⁻³, l’approximation <i>z</i> ≈ <i>G M</i>/(<i>r c</i>²) est excellente ; au-delà, prends la racine.'},
  note:'Pour la Terre, (<i>G M</i>/<i>c</i>²)(1/<i>R</i> − 1/<i>r</i>) du chapitre précédent est le développement au premier ordre du rapport exact √(1 − <i>r</i><sub>s</sub>/<i>r</i>)/√(1 − <i>r</i><sub>s</sub>/<i>R</i>).'},
 {h:'La naine blanche',p:'Sirius B est une naine blanche de masse 1,02 masse solaire (1,99·10³⁰ kg) et de rayon 5,8·10⁶ m (<i>G</i> = 6,67·10⁻¹¹, <i>c</i> = 3,00·10⁸ m/s). Quel est le décalage vers le rouge <i>z</i> d’une raie émise à sa surface, vue de loin&nbsp;? Donne la réponse en unités de 10⁻⁴, arrondie au centième.',lab:'z =',unit:'× 10⁻⁴',ans:2.595,tol:.02,
  why:'r<sub>s</sub> = 2 × 6,67·10⁻¹¹ × 1,02 × 1,99·10³⁰/(9·10¹⁶) ≈ 3009 m, et r<sub>s</sub>/R ≈ 5,19·10⁻⁴. Exact : z = 1/√(1 − 5,19·10⁻⁴) − 1 ≈ 2,595·10⁻⁴ ; l’approximation r<sub>s</sub>/(2R) = 2,594·10⁻⁴ est indiscernable. Ce décalage, mesuré en 1925 puis affiné, a été l’un des premiers tests de la théorie.'},
 {h:'La lumière déviée par le Soleil',p:`<p>Au chapitre précédent, la lumière tombait dans l’ascenseur. Autour du Soleil, un rayon venu d’une étoile lointaine et passant à la distance <i>b</i> du centre est donc dévié d’un petit angle, et l’étoile paraît décalée vers l’extérieur du disque solaire.</p>
<div class="prop"><p><b>Déviation d’un rayon lumineux</b> passant à la distance <i>b</i> d’une masse <i>M</i> : <b><i>δ</i> = 4<i>G M</i>/(<i>c</i>² <i>b</i>) = 2<i>r</i><sub>s</sub>/<i>b</i></b> (en radians). Pour un rayon qui frôle le Soleil (<i>b</i> = 6,96·10⁸ m) : <i>δ</i> = 4 × 1,327·10²⁰/(9·10¹⁶ × 6,96·10⁸) ≈ 8,48·10⁻⁶ rad = 1,75″ (secondes d’arc, 1″ = 1/3600 de degré = 4,85·10⁻⁶ rad).</p></div>
<div class="why"><p>Un calcul newtonien, qui traite le photon comme une particule de vitesse <i>c</i> attirée par <i>G M</i>/<i>r</i>², donne 2<i>G M</i>/(<i>c</i>²<i>b</i>) : exactement la <b>moitié</b>. C’est aussi ce que donne le seul principe d’équivalence, qui ne concerne que le coefficient temporel de la métrique. L’autre moitié vient du coefficient spatial 1/(1 − <i>r</i><sub>s</sub>/<i>r</i>) : l’espace lui-même est courbé, pas seulement le temps. Einstein avait d’ailleurs d’abord publié la valeur newtonienne, en 1911, avant de la corriger avec la théorie complète en 1915.</p></div>
<div class="ex"><p>Le 29 mai 1919, pendant une éclipse totale, deux expéditions britanniques (île de Príncipe et Sobral, au Brésil) photographient les étoiles proches du disque solaire masqué, puis comparent avec des clichés du même champ pris la nuit, six mois plus tôt. Les étoiles sont déplacées de 1,6″ à 2,0″ selon les plaques : compatible avec 1,75″, incompatible avec 0,87″. La relativité générale fait la une des journaux.</p></div>
<div class="warn"><p>La déviation décroît en 1/<i>b</i> : à deux rayons solaires du centre, elle ne vaut plus que 0,87″. Aujourd’hui, les mesures radio sur des quasars confirment la formule à 10⁻⁴ près.</p></div>`,
  fig:(()=>{ const P=plane({x:[-9,9],y:[-3.2,3.6],grid:false,axes:false,w:320}); P.circ(0,0,1.2,{fill:'var(--spark)',fo:.6,c:'var(--spark)',w:2}); P.text(0,0,'Soleil',{a:'middle',dy:4,s:11});
    const b=1.45, k=0.09; P.fn(x=>b+k*x*x/16,{from:-8.5,to:8.5,c:'var(--accent)',n:120}); P.seg(-8.5,b+k*8.5*8.5/16,8.5,b+k*8.5*8.5/16,{c:'var(--muted)',w:1,dash:true});
    P.dot(-8.3,b+k*8.5*8.5/16,{c:'var(--ink)',r:4,l:'étoile',dx:-8,dy:-10}); P.dot(8.3,b+k*8.5*8.5/16,{c:'var(--ink)',r:4,l:'Terre',dx:-30,dy:-10});
    P.text(0,b,'b',{dx:6,dy:-4,s:12,c:'var(--accent)'}); P.seg(0,0,0,b,{c:'var(--accent)',w:1,dash:true}); P.text(5,b+k*25/16,'δ',{dy:-8,s:13,c:'var(--accent)'}); P.text(0,-2.4,'déviation très exagérée',{a:'middle',s:11,c:'var(--muted)'}); return P.svg(); })()},
 {h:'Un rayon frôle Jupiter',p:'Un rayon lumineux frôle Jupiter (masse 1,90·10²⁷ kg, rayon 7,15·10⁷ m ; <i>G</i> = 6,67·10⁻¹¹, <i>c</i> = 3,00·10⁸ m/s). De quel angle est-il dévié&nbsp;? Donne la réponse en millisecondes d’arc (1″ = 4,85·10⁻⁶ rad), arrondie au dixième.',lab:'δ =',unit:'mas',ans:16.25,tol:.15,
  why:'δ = 4GM/(c²b) = 4 × 6,67·10⁻¹¹ × 1,90·10²⁷/(9·10¹⁶ × 7,15·10⁷) ≈ 7,88·10⁻⁸ rad. En secondes d’arc : 7,88·10⁻⁸/4,85·10⁻⁶ ≈ 0,0162″ = 16,2 mas. Cette déviation a été mesurée par interférométrie radio.'},
 {h:'L’avance du périhélie de Mercure',p:`<p>Chez Newton, une planète seule autour du Soleil décrit une ellipse fixe : le périhélie (point le plus proche du Soleil) reste au même endroit, tour après tour. En tenant compte de l’attraction des autres planètes, le périhélie de Mercure tourne lentement, de 532″ par siècle. Mais les observations donnent 575″ : il manque <b>43″ par siècle</b>, et au XIXᵉ siècle on a cherché en vain une planète inconnue, « Vulcain », pour l’expliquer.</p>
<div class="idea"><p>Dans la métrique de Schwarzschild, l’énergie d’une orbite contient, en plus du terme newtonien −<i>G M</i>/<i>r</i> et du terme centrifuge, un petit terme attractif supplémentaire en 1/<i>r</i>³. Il est d’autant plus fort que la planète est proche du Soleil et que son orbite est allongée. L’ellipse ne se referme plus exactement : à chaque tour, le périhélie avance un peu, et l’orbite ressemble à une rosace.</p></div>
<div class="prop"><p><b>Avance du périhélie par révolution</b> : <b><i>Δφ</i> = 6π<i>G M</i>/(<i>c</i>² <i>a</i> (1 − <i>e</i>²))</b> radians, où <i>a</i> est le demi-grand axe et <i>e</i> l’excentricité. On peut l’écrire 3π <i>r</i><sub>s</sub>/(<i>a</i>(1 − <i>e</i>²)) : encore un effet d’ordre <i>r</i><sub>s</sub>/<i>a</i>.</p></div>
<div class="ex"><p>Pour Mercure, <i>a</i> = 5,79·10¹⁰ m et <i>e</i> = 0,206 : l’avance vaut 5,0·10⁻⁷ rad par tour, soit 0,103″. En 88 jours de révolution, c’est imperceptible ; mais Mercure fait 415 tours par siècle, et les 43″ sont retrouvés sans aucun paramètre libre. C’est la première confirmation qu’Einstein a obtenue, en novembre 1915, « le cœur battant ».</p></div>`,
  fig:(()=>{ const P=plane({x:[-3.3,3.3],y:[-2.6,2.6],grid:false,axes:false,w:300}); const a=2,e=0.55,p=a*(1-e*e); P.dot(0,0,{c:'var(--spark)',r:8});
    for(let k=0;k<4;k++){ const w=k*rad(28); P.curve(t=>p/(1+e*Math.cos(t))*Math.cos(t+w),t=>p/(1+e*Math.cos(t))*Math.sin(t+w),0,2*Math.PI,{c:k==0?'var(--accent)':'var(--muted)',w:k==0?3:1.5,op:k==0?1:.7}); P.dot(a*(1-e)*Math.cos(w),a*(1-e)*Math.sin(w),{c:'var(--bad)',r:4}); }
    P.text(0,-2.4,'périhélie qui avance (exagéré)',{a:'middle',s:11,c:'var(--muted)'}); return P.svg(); })()},
 {kind:'Méthode',h:'Calculer une avance de périhélie',p:`<p><b>Quand</b> : on demande le décalage du périhélie d’une planète, d’un astéroïde ou d’une étoile en orbite, par révolution ou par siècle.</p><p><b>Pourquoi</b> : la formule <i>Δφ</i> = 6π<i>G M</i>/(<i>c</i>²<i>a</i>(1 − <i>e</i>²)) donne un angle en radians par tour. Pour le convertir en un chiffre observable, on le passe en secondes d’arc et on le multiplie par le nombre de tours dans la période considérée.</p><p><b>Comment</b> : 1. Calcule <i>G M</i>/<i>c</i>² (pour le Soleil, 1,475·10³ m). 2. Divise par <i>a</i>(1 − <i>e</i>²), multiplie par 6π : c’est <i>Δφ</i> en radians. 3. Convertis en secondes d’arc : × 206 265. 4. Nombre de révolutions par siècle : 36 525 jours divisés par la période en jours. 5. Multiplie.</p>`,
  demo:{enonce:'Mercure : <i>a</i> = 5,79·10¹⁰ m, <i>e</i> = 0,206, période 87,97 jours. Soleil : <i>M</i> = 1,99·10³⁰ kg. <i>G</i> = 6,67·10⁻¹¹, <i>c</i> = 3,00·10⁸ m/s. Calcule l’avance relativiste du périhélie par siècle.',
   etapes:[
    {f:'<i>G M</i>/<i>c</i>² = 6,67·10⁻¹¹ × 1,99·10³⁰/(9,00·10¹⁶) ≈ 1,475·10³ m',w:'C’est la moitié du rayon de Schwarzschild du Soleil. Une longueur : le résultat final sera bien sans unité.'},
    {f:'<i>a</i>(1 − <i>e</i>²) = 5,79·10¹⁰ × (1 − 0,0424) ≈ 5,544·10¹⁰ m',w:'L’excentricité augmente l’effet : à <i>a</i> égal, une orbite allongée passe plus près du Soleil.'},
    {f:'<i>Δφ</i> = 6π × 1,475·10³/5,544·10¹⁰ ≈ 5,01·10⁻⁷ rad, soit 5,01·10⁻⁷ × 206 265 ≈ 0,103″ par tour',w:'Un radian vaut 206 265 secondes d’arc.'},
    {f:'36 525/87,97 ≈ 415,2 tours par siècle, donc 0,103″ × 415,2 ≈ 43″ par siècle',w:'L’effet par tour est minuscule, mais il s’accumule sans jamais se compenser.'},
   ],
   conclusion:'42,9″ par siècle, pour 43,0″ ± 0,1″ observés. La Terre, plus loin et sur une orbite presque circulaire, n’avance que de 3,8″ par siècle.'}},
 {h:'Le périhélie de Vénus',p:'Vénus : <i>a</i> = 1,082·10¹¹ m, <i>e</i> = 0,0068, période 224,7 jours. Soleil : <i>M</i> = 1,99·10³⁰ kg, <i>G</i> = 6,67·10⁻¹¹, <i>c</i> = 3,00·10⁸ m/s, 1 rad = 206 265″. Quelle est l’avance relativiste de son périhélie par siècle (36 525 jours)&nbsp;? Arrondis au dixième de seconde d’arc.',lab:'Δφ =',unit:'″/siècle',ans:8.61,tol:.08,
  why:'Δφ = 6π × 1,475·10³/(1,082·10¹¹ × (1 − 4,6·10⁻⁵)) ≈ 2,57·10⁻⁷ rad = 0,0530″ par tour. Vénus fait 36 525/224,7 ≈ 162,5 tours par siècle : 0,0530 × 162,5 ≈ 8,6″ par siècle. L’orbite étant presque circulaire, le périhélie de Vénus est mal défini et cette avance est difficile à mesurer.'},
 {h:'Pourquoi la pomme tombe-t-elle&nbsp;?',p:'En relativité générale, quelle est la bonne description de la chute d’une pomme vers le sol&nbsp;?',
  opts:['La Terre exerce sur la pomme une force qui la tire, et la pomme résiste à cause de sa masse inerte','La pomme suit une géodésique de l’espace-temps courbé par la Terre ; c’est le sol qui l’empêche de la suivre et qui la pousse','La pomme est attirée par la courbure, qui agit comme une force de direction variable','La pomme tombe parce que le temps s’écoule plus vite au sol, ce qui l’aspire vers le bas'],ans:1,
  why:'La pomme en chute libre ne subit aucune force : elle va « tout droit » dans un espace-temps courbe. Posée sur la table, elle est écartée de sa géodésique par la réaction de la table, et c’est cette force qu’on sent comme un poids. La différence de rythme des horloges est une conséquence de la même courbure, pas une cause.'},
 {kind:'Récapitulatif',h:'Ce qu’il faut retenir',p:`<div class="keep"><ul>
<li>La gravitation n’est pas une force : elle agit sur tout de la même façon, s’efface en chute libre et doit se propager à vitesse finie. Elle est une <b>courbure de l’espace-temps</b>.</li>
<li><b>Géométrie courbe</b> : sur une sphère de rayon <i>R</i>, l’excès angulaire d’un triangle vaut <i>E</i> = <i>A</i>/<i>R</i>². Une <b>géodésique</b> va tout droit (grands cercles) ; deux géodésiques voisines se rapprochent ou s’écartent : c’est ce que Newton appelait force.</li>
<li>La <b>métrique</b> donne d<i>s</i>² avec des coefficients qui dépendent du lieu. Les corps libres suivent les géodésiques ; la matière fixe la métrique.</li>
<li><b>Schwarzschild</b> : d<i>s</i>² = (1 − <i>r</i><sub>s</sub>/<i>r</i>)<i>c</i>²d<i>t</i>² − d<i>r</i>²/(1 − <i>r</i><sub>s</sub>/<i>r</i>) − <i>r</i>²dΩ², avec <i>r</i><sub>s</sub> = 2<i>GM</i>/<i>c</i>² (2,95 km pour le Soleil, 8,9 mm pour la Terre).</li>
<li><b>Horloge en <i>r</i></b> : d<i>τ</i> = √(1 − <i>r</i><sub>s</sub>/<i>r</i>) d<i>t</i> ; fréquence reçue à l’infini <i>f</i><sub>∞</sub> = <i>f</i><sub>e</sub>√(1 − <i>r</i><sub>s</sub>/<i>r</i>), décalage <i>z</i> = 1/√(1 − <i>r</i><sub>s</sub>/<i>r</i>) − 1 ≈ <i>r</i><sub>s</sub>/(2<i>r</i>) au premier ordre.</li>
<li><b>Déviation de la lumière</b> : <i>δ</i> = 4<i>GM</i>/(<i>c</i>²<i>b</i>) = 1,75″ au bord du Soleil, le double de la valeur newtonienne. Éclipse de 1919.</li>
<li><b>Avance du périhélie</b> : <i>Δφ</i> = 6π<i>GM</i>/(<i>c</i>²<i>a</i>(1 − <i>e</i>²)) par tour ; 43″ par siècle pour Mercure (1 rad = 206 265″).</li>
</ul></div>
<p>Méthodes : lire le facteur 1 − <i>r</i><sub>s</sub>/<i>r</i> pour un décalage exact et le comparer au premier ordre ; calculer une avance de périhélie (radians par tour, puis secondes d’arc par siècle).</p>`},
 {kind:'Problème',h:'Le pulsar et sa raie',
  p:'Un pulsar est une étoile à neutrons de masse 2,0 masses solaires (<i>M</i>☉ = 1,99·10³⁰ kg) et de rayon 11 km. Un télescope lointain observe une raie d’absorption produite à sa surface, dont la longueur d’onde au repos est <i>λ</i><sub>e</sub> = 400 nm. Données : <i>G</i> = 6,67·10⁻¹¹, <i>c</i> = 3,00·10⁸ m/s. On cherche ce que voit le télescope et ce qu’une horloge posée sur l’étoile ferait.',
  parts:[
   {q:'a) Quel est le rayon de Schwarzschild du pulsar&nbsp;? Arrondis au dixième de kilomètre.',lab:'rₛ =',unit:'km',ans:5.9,tol:.05,hint:'<i>r</i><sub>s</sub> = 2<i>GM</i>/<i>c</i>², avec <i>M</i> = 2,0 × 1,99·10³⁰ kg.',why:'r<sub>s</sub> = 2 × 6,67·10⁻¹¹ × 3,98·10³⁰/(9·10¹⁶) ≈ 5,90·10³ m = 5,9 km : plus de la moitié du rayon de l’étoile.'},
   {q:'b) Quelle longueur d’onde le télescope mesure-t-il&nbsp;? Arrondis au nanomètre.',lab:'λ∞ =',unit:'nm',ans:587.4,tol:1,hint:'<i>λ</i><sub>∞</sub> = <i>λ</i><sub>e</sub>/√(1 − <i>r</i><sub>s</sub>/<i>R</i>).',why:'1 − r<sub>s</sub>/R = 1 − 5,90/11 ≈ 0,464, √0,464 ≈ 0,681. λ<sub>∞</sub> = 400/0,681 ≈ 587 nm : du violet au jaune.'},
   {q:'c) Si on avait utilisé l’approximation du premier ordre <i>z</i> ≈ <i>r</i><sub>s</sub>/(2<i>R</i>), on aurait trouvé…',opts:['z ≈ 0,27, soit 507 nm : l’approximation est ici inutilisable','z ≈ 0,47, la même valeur : l’approximation est toujours excellente','z ≈ 0,54, soit 616 nm : l’approximation surestime l’effet','z ≈ 0,13, car il faut diviser par 4'],ans:0,hint:'Calcule <i>r</i><sub>s</sub>/(2<i>R</i>) et compare au <i>z</i> exact 1/√(1 − <i>r</i><sub>s</sub>/<i>R</i>) − 1.',why:'r<sub>s</sub>/(2R) = 5,90/22 ≈ 0,27, alors que z exact = 1/0,681 − 1 ≈ 0,47. Avec r<sub>s</sub>/R = 0,54, on est loin du régime presque plat : le premier ordre sous-estime l’effet de 40 %.'},
   {q:'d) Une horloge posée à la surface du pulsar bat pendant 1 an de son temps propre. Combien de temps s’est écoulé pour l’observateur lointain&nbsp;? Arrondis au centième d’année.',lab:'t =',unit:'ans',ans:1.468,tol:.01,hint:'d<i>τ</i> = √(1 − <i>r</i><sub>s</sub>/<i>R</i>) d<i>t</i> : le temps lointain est le plus long.',why:'Δt = Δτ/√(1 − r<sub>s</sub>/R) = 1/0,681 ≈ 1,47 an. Le facteur est le même que pour les longueurs d’onde : 1 + z.'},
  ],
  sol:'<p><i>r</i><sub>s</sub> = 2<i>GM</i>/<i>c</i>² ≈ 5,9 km, à comparer au rayon 11 km : <i>r</i><sub>s</sub>/<i>R</i> ≈ 0,54. Le facteur temporel de la métrique de Schwarzschild vaut 1 − 0,536 ≈ 0,464 à la surface, de racine 0,681.</p><p>Une horloge de surface bat à 68 % du rythme lointain : un an sur le pulsar correspond à 1,47 an au loin. La raie émise à 400 nm est reçue à 400/0,681 ≈ 587 nm, soit <i>z</i> ≈ 0,47.</p><p>L’approximation <i>z</i> ≈ <i>GM</i>/(<i>Rc</i>²) = 0,27 est très mauvaise ici : elle n’est valable que pour <i>r</i><sub>s</sub>/<i>R</i> ≪ 1 (Soleil : 4·10⁻⁶ ; naine blanche : 5·10⁻⁴). Les étoiles à neutrons sont les objets les plus relativistes qui aient une surface, et la mesure de ce décalage sert à contraindre le rapport <i>M</i>/<i>R</i>.</p>'},
 {kind:'Problème',h:'Peser une étoile avec la lumière',
  p:'Lors d’une éclipse, on photographie une étoile dont la lumière passe à <i>b</i> = 2,0 rayons solaires du centre du Soleil (<i>R</i>☉ = 6,96·10⁸ m, <i>M</i>☉ = 1,99·10³⁰ kg, <i>G</i> = 6,67·10⁻¹¹, <i>c</i> = 3,00·10⁸ m/s, 1 rad = 206 265″). Les meilleures plaques de l’époque mesurent une position à 0,1″ près. On veut savoir ce que l’éclipse peut montrer, et ce qu’on pourrait apprendre d’une autre étoile.',
  parts:[
   {q:'a) De quel angle cette étoile paraît-elle déplacée&nbsp;? Arrondis au centième de seconde d’arc.',lab:'δ =',unit:'″',ans:0.874,tol:.01,hint:'<i>δ</i> = 4<i>GM</i>/(<i>c</i>²<i>b</i>) avec <i>b</i> = 2 × 6,96·10⁸ m, puis convertis en secondes d’arc.',why:'δ = 4 × 1,327·10²⁰/(9·10¹⁶ × 1,392·10⁹) ≈ 4,24·10⁻⁶ rad, soit 4,24·10⁻⁶ × 206 265 ≈ 0,87″. La moitié de la déviation au bord, car b a doublé.'},
   {q:'b) Jusqu’à quelle distance du centre, en rayons solaires, la déviation reste-t-elle supérieure à 0,10″&nbsp;? Arrondis au dixième.',lab:'b =',unit:'R☉',ans:17.5,tol:.2,hint:'Résous 4<i>GM</i>/(<i>c</i>²<i>b</i>) = 0,10″ convertie en radians, puis divise <i>b</i> par 6,96·10⁸ m.',why:'0,10″ = 4,85·10⁻⁷ rad. b = 4GM/(c² × 4,85·10⁻⁷) = 5,90·10³/4,85·10⁻⁷ ≈ 1,22·10¹⁰ m ≈ 17,5 R☉. Les étoiles exploitables en 1919 étaient toutes dans ce rayon.'},
   {q:'c) Si la gravitation newtonienne s’appliquait à la lumière comme à une particule de vitesse <i>c</i>, le déplacement de la question a) serait…',opts:['le même, 0,87″ : la déviation ne dépend que de <i>GM</i>/<i>b</i>','deux fois plus petit, 0,44″ : il manque la courbure de l’espace','nul : une particule sans masse n’est pas attirée','deux fois plus grand, 1,75″'],ans:1,hint:'Souviens-toi de la part du coefficient spatial de la métrique.',why:'Le calcul newtonien (et le seul principe d’équivalence) donne 2GM/(c²b), la moitié de la valeur complète. La courbure de l’espace, portée par le coefficient 1/(1 − r<sub>s</sub>/r), fournit l’autre moitié. Les mesures de 1919 ont tranché en faveur de 4GM/(c²b).'},
   {q:'d) Une étoile lointaine passe derrière une naine blanche inconnue et paraît déplacée de 10 millisecondes d’arc alors que sa lumière passe à <i>b</i> = 1,0·10¹¹ m du centre de la naine. Quelle est la masse de la naine blanche, en masses solaires&nbsp;? Arrondis au centième.',lab:'M =',unit:'M☉',ans:0.822,tol:.015,hint:'Retourne la formule : <i>M</i> = <i>δ c</i>² <i>b</i>/(4<i>G</i>), avec <i>δ</i> en radians.',why:'δ = 10·10⁻³ × 4,85·10⁻⁶ = 4,85·10⁻⁸ rad. M = δc²b/(4G) = 4,85·10⁻⁸ × 9·10¹⁶ × 10¹¹/(4 × 6,67·10⁻¹¹) = 4,37·10²⁰/2,67·10⁻¹⁰ ≈ 1,64·10³⁰ kg = 0,82 M☉.'},
  ],
  sol:'<p>La déviation d’un rayon passant à la distance <i>b</i> vaut <i>δ</i> = 4<i>GM</i>/(<i>c</i>²<i>b</i>) = 2<i>r</i><sub>s</sub>/<i>b</i>. Pour le Soleil, 2<i>r</i><sub>s</sub> = 5,90 km : à <i>b</i> = 2<i>R</i>☉, <i>δ</i> = 5,90·10³/1,392·10⁹ = 4,24·10⁻⁶ rad = 0,87″.</p><p>La déviation décroît comme 1/<i>b</i> : elle reste au-dessus de 0,10″ jusqu’à <i>b</i> = 5,90·10³/4,85·10⁻⁷ ≈ 1,2·10¹⁰ m, soit 17,5 rayons solaires. C’est ce qui limitait le nombre d’étoiles utilisables en 1919.</p><p>Newton ou le seul principe d’équivalence ne donnent que la moitié ; la courbure spatiale complète le compte.</p><p>Inversement, la formule pèse une masse : <i>M</i> = <i>δc</i>²<i>b</i>/(4<i>G</i>). C’est le principe des microlentilles gravitationnelles, avec lesquelles on a mesuré la masse de naines blanches et détecté des exoplanètes.</p>'},
]},
/* ================= 3. TROUS NOIRS ================= */
{subj:'phy', sem:'rel', id:'phy-rg-trous-noirs', h:'Trous noirs', p:'Rayon de Schwarzschild, horizon, forces de marée, orbites extrêmes, images de M87* et de Sagittarius A*, et l’évaporation de Hawking.', steps:[
 {h:'Le rayon de Schwarzschild',p:`<p>Dans la métrique de Schwarzschild, le facteur 1 − <i>r</i><sub>s</sub>/<i>r</i> s’annule en <i>r</i> = <i>r</i><sub>s</sub>. Pour une étoile ordinaire, ce rayon est enfoui très profondément sous la surface, là où la solution ne s’applique plus (elle vaut pour le vide extérieur). Mais si toute la masse est comprimée à l’intérieur de <i>r</i><sub>s</sub>, le facteur s’annule réellement : on a un <b>trou noir</b>.</p>
<div class="def"><p>Le <b>rayon de Schwarzschild</b> d’une masse <i>M</i> est <b><i>r</i><sub>s</sub> = 2<i>G M</i>/<i>c</i>²</b>. La sphère de rayon <i>r</i><sub>s</sub> s’appelle l’<b>horizon des événements</b>. Un objet dont tout le contenu tient dans son rayon de Schwarzschild est un trou noir.</p></div>
<div class="idea"><p>Un raisonnement newtonien, dû à Michell (1783) et Laplace, donne la même formule par hasard : la vitesse de libération √(2<i>G M</i>/<i>R</i>) atteint <i>c</i> quand <i>R</i> = 2<i>G M</i>/<i>c</i>². « Même la lumière ne pourrait s’en échapper. » En relativité générale, la conclusion est plus forte : rien ne sort de l’horizon, pas même un signal ralenti, parce que la géométrie elle-même se referme.</p></div>
<div class="ex"><p><i>r</i><sub>s</sub> est proportionnel à la masse : 2<i>G</i>/<i>c</i>² = 1,48·10⁻²⁷ m par kilogramme. Pour le Soleil (1,99·10³⁰ kg) : 2,95 km. Pour la Terre (5,97·10²⁴ kg) : 8,85 mm, la taille d’une bille. Pour faire un trou noir de la Terre, il faudrait la compresser d’un facteur (6,37·10⁶/8,85·10⁻³)³ ≈ 4·10²⁶ en volume.</p></div>
<div class="warn"><p>Un trou noir n’est pas un « aspirateur ». Loin de lui, à <i>r</i> ≫ <i>r</i><sub>s</sub>, son champ est celui de Newton : si le Soleil devenait un trou noir de même masse, la Terre garderait exactement son orbite. Seule la région à quelques <i>r</i><sub>s</sub> est nouvelle.</p></div>`},
 {kind:'Méthode',h:'Calculer un rayon de Schwarzschild et le comparer à l’objet',p:`<p><b>Quand</b> : on veut savoir si un objet est un trou noir, à quelle distance les effets relativistes deviennent forts, ou simplement donner l’échelle d’un trou noir de masse donnée.</p><p><b>Pourquoi</b> : <i>r</i><sub>s</sub> = 2<i>G M</i>/<i>c</i>² est linéaire en <i>M</i>. Une fois connu <i>r</i><sub>s</sub>(1 M☉) = 2,95 km, on multiplie par la masse en masses solaires. Le rapport <i>r</i><sub>s</sub>/<i>R</i> dit si l’objet est « relativiste » (proche de 1) ou presque newtonien (≪ 1).</p><p><b>Comment</b> : 1. Masse en kg (ou en M☉). 2. <i>r</i><sub>s</sub> = 2<i>G M</i>/<i>c</i>², ou 2,95 km × <i>M</i>/M☉. 3. Compare à une taille parlante : rayon de l’objet, rayon du Soleil (6,96·10⁸ m), unité astronomique (1,496·10¹¹ m). 4. Si on demande une densité moyenne, <i>ρ</i> = <i>M</i>/(4π<i>r</i><sub>s</sub>³/3) ∝ 1/<i>M</i>² : les gros trous noirs sont peu denses.</p>`,
  demo:{enonce:'a) Un trou noir stellaire a 10 masses solaires. b) Sagittarius A*, au centre de la Voie lactée, a 4,0·10⁶ masses solaires. Donne leur rayon de Schwarzschild, compare-le au rayon du Soleil et à l’unité astronomique, et calcule la densité moyenne du second (<i>M</i>☉ = 1,99·10³⁰ kg, <i>G</i> = 6,67·10⁻¹¹, <i>c</i> = 3,00·10⁸ m/s).',
   etapes:[
    {f:'<i>r</i><sub>s</sub>(1 M☉) = 2 × 6,67·10⁻¹¹ × 1,99·10³⁰/(9,00·10¹⁶) ≈ 2,95·10³ m',w:'On calcule une fois pour toutes la valeur pour une masse solaire.'},
    {f:'10 M☉ : <i>r</i><sub>s</sub> = 29,5 km',w:'Linéaire en la masse. Un objet de dix soleils dans une sphère de la taille d’une ville.'},
    {f:'4,0·10⁶ M☉ : <i>r</i><sub>s</sub> = 4,0·10⁶ × 2,95 km ≈ 1,18·10¹⁰ m ≈ 17 <i>R</i>☉ ≈ 0,079 ua',w:'Sagittarius A* tiendrait bien à l’intérieur de l’orbite de Mercure (0,39 ua).'},
    {f:'<i>ρ</i> = <i>M</i>/(4π<i>r</i><sub>s</sub>³/3) = 7,96·10³⁶/(4π × (1,18·10¹⁰)³/3) ≈ 1,2·10⁶ kg/m³',w:'Mille fois la densité de l’eau seulement : à peu près une naine blanche. Pour 10 M☉, on trouverait 1,9·10¹⁷ kg/m³, plus qu’un noyau atomique.'},
   ],
   conclusion:'29,5 km et 1,18·10⁷ km. La densité moyenne décroît comme 1/<i>M</i>² : un trou noir de quelques milliards de masses solaires serait moins dense que l’air.'}},
 {h:'Le géant de M87',p:'Le trou noir au centre de la galaxie M87 a une masse de 6,5·10⁹ masses solaires (<i>M</i>☉ = 1,99·10³⁰ kg, <i>G</i> = 6,67·10⁻¹¹, <i>c</i> = 3,00·10⁸ m/s). Quel est son rayon de Schwarzschild, en unités astronomiques (1 ua = 1,496·10¹¹ m)&nbsp;? Arrondis à l’unité.',lab:'rₛ =',unit:'ua',ans:128,tol:1.5,
  why:'r<sub>s</sub> = 6,5·10⁹ × 2,95 km ≈ 1,92·10¹³ m, soit 1,92·10¹³/1,496·10¹¹ ≈ 128 ua. Plus de quatre fois le rayon de l’orbite de Neptune (30 ua).'},
 {h:'L’horizon des événements',p:`<p>Que se passe-t-il à <i>r</i> = <i>r</i><sub>s</sub>&nbsp;? Il faut distinguer deux points de vue, celui de l’astronaute qui tombe et celui de l’observateur resté au loin.</p>
<div class="idea"><p><b>Pour celui qui tombe</b>, l’horizon n’est marqué par rien de spécial : pas de mur, pas de flash. Il franchit <i>r</i><sub>s</sub> en un temps propre fini, continue à voir l’extérieur, et atteint le centre peu après (environ 10⁻⁵ s pour 1 M☉). Le principe d’équivalence l’exige : en chute libre, localement, tout est normal. Ce qui change, c’est qu’une fois à l’intérieur, aucune trajectoire, pas même celle de la lumière, ne le ramène vers <i>r</i> &gt; <i>r</i><sub>s</sub> : la direction « vers le centre » est devenue aussi inéluctable que la direction « vers le futur ».</p></div>
<div class="prop"><p><b>Pour l’observateur lointain</b>, les signaux envoyés depuis <i>r</i> arrivent avec la fréquence <i>f</i><sub>∞</sub> = <i>f</i><sub>e</sub>√(1 − <i>r</i><sub>s</sub>/<i>r</i>). Quand <i>r</i> → <i>r</i><sub>s</sub>, ce facteur tend vers 0 : les signaux sont de plus en plus <b>rouges</b> et de plus en plus <b>espacés</b>. L’astronaute semble ralentir, se figer juste au-dessus de l’horizon, et son image s’éteint. On ne le voit jamais franchir <i>r</i><sub>s</sub>.</p></div>
<div class="why"><p>Les deux récits sont compatibles : le temps <i>t</i> de la métrique est celui de l’observateur lointain, et le franchissement a lieu à <i>t</i> infini dans cette coordonnée, mais à <i>τ</i> fini pour l’astronaute. L’horizon est une surface où la coordonnée <i>t</i> cesse d’être un bon repère, pas un lieu où la physique s’arrête. En pratique, l’image s’évanouit en quelques dizaines de microsecondes pour un trou noir stellaire : le décalage devient tel que plus aucun photon n’est détectable.</p></div>
<div class="ex"><p>À <i>r</i> = 2<i>r</i><sub>s</sub>, le facteur vaut √(1/2) = 0,707 : une horloge y bat à 71 % du rythme lointain, et <i>z</i> = 0,41. À <i>r</i> = 1,01<i>r</i><sub>s</sub>, √(1 − 1/1,01) ≈ 0,0995 : rythme divisé par 10, <i>z</i> ≈ 9. Déplace le curseur vers l’horizon pour voir la divergence.</p></div>`,
  params:[{id:'x',l:'Distance r/rₛ',min:1.05,max:6,step:.05,v:3,u:''}],
  draw:v=>{ const P=plane({x:[0.3,6.3],y:[-0.5,5.2],grid:true,step:1,lab:1,w:320,h:220}); P.seg(1,-0.5,1,5.2,{c:'var(--bad)',w:2,dash:true}).text(1,5.0,'horizon',{dx:4,s:11,c:'var(--bad)'});
    P.fn(x=>x>1.0005?1/Math.sqrt(1-1/x)-1:NaN,{from:1,to:6.3,c:'var(--bad)',n:400}); P.fn(x=>x>1?Math.sqrt(1-1/x):NaN,{from:1,to:6.3,c:'var(--accent)',n:400});
    const f=Math.sqrt(1-1/v.x), z=1/f-1; P.dot(v.x,f,{c:'var(--accent)',l:'rythme '+fmt(f,2),dx:8,dy:14}); if(z<5.1) P.dot(v.x,z,{c:'var(--bad)',l:'z = '+fmt(z,2)}); P.text(6.2,0,'r/rₛ',{a:'end',dy:16,s:11,c:'var(--muted)'}); return P.svg(); },
  info:v=>{ const f=Math.sqrt(1-1/v.x); return `À <i>r</i> = ${fmt(v.x,2)} <i>r</i><sub>s</sub> : une horloge bat à ${fmt(100*f,1)} % du rythme lointain ; une raie émise à 500 nm est reçue à ${fmt(500/f,0)} nm (<i>z</i> = ${fmt(1/f-1,2)}).`; },
  note:'Bleu : √(1 − rₛ/r), rythme des horloges vu de loin. Rouge : le décalage z, qui diverge à l’horizon.'},
 {h:'Près de l’horizon',p:'Une sonde immobile à <i>r</i> = 1,25 <i>r</i><sub>s</sub> d’un trou noir émet un signal de longueur d’onde 600 nm. Quel décalage <i>z</i> mesure un observateur lointain&nbsp;? Arrondis au centième.',lab:'z =',unit:'',ans:1.236,tol:.006,
  why:'1 − r<sub>s</sub>/r = 1 − 0,8 = 0,2, √0,2 ≈ 0,447. z = 1/0,447 − 1 ≈ 1,24 : le signal est reçu à 600 × 2,24 ≈ 1340 nm, dans l’infrarouge.'},
 {h:'Les forces de marée',p:`<p>Si l’horizon ne fait rien de spécial, qu’est-ce qui rend un trou noir dangereux de près&nbsp;? Pas la gravité elle-même, qu’on ne sent pas en chute libre, mais ses <b>différences</b> d’un point à l’autre du corps : les forces de marée, déjà rencontrées comme limite du principe d’équivalence.</p>
<div class="prop"><p>L’accélération de gravité newtonienne vaut <i>a</i>(<i>r</i>) = <i>G M</i>/<i>r</i>². Sa dérivée est d<i>a</i>/d<i>r</i> = −2<i>G M</i>/<i>r</i>³. Entre les deux extrémités d’un corps de longueur <i>L</i> aligné sur la direction radiale, la différence d’accélération vaut donc <b><i>Δa</i> ≈ 2<i>G M L</i>/<i>r</i>³</b>. Les pieds sont tirés plus fort que la tête : le corps est <b>étiré</b> radialement (et comprimé latéralement). Cette formule reste correcte en relativité générale pour un observateur en chute libre, y compris à l’horizon.</p></div>
<div class="idea"><p>Sur Terre, pour <i>L</i> = 2 m : <i>Δa</i> = 2 × 3,98·10¹⁴ × 2/(6,37·10⁶)³ ≈ 3·10⁻⁶ m/s², imperceptible. Près d’un trou noir stellaire, <i>r</i> est des millions de fois plus petit et <i>Δa</i> varie en 1/<i>r</i>³ : l’étirement dépasse largement ce que les tissus supportent, bien avant l’horizon. On parle de <b>spaghettification</b>.</p></div>
<div class="why"><p>À l’horizon, <i>r</i> = <i>r</i><sub>s</sub> = 2<i>G M</i>/<i>c</i>², donc <i>Δa</i> = 2<i>G M L</i>/<i>r</i><sub>s</sub>³ = <i>L c</i>⁶/(4<i>G</i>²<i>M</i>²) : elle décroît comme <b>1/<i>M</i>²</b>. Plus le trou noir est massif, plus son horizon est loin du centre et plus la marée y est douce. On peut franchir sans dommage l’horizon d’un trou noir supermassif ; celui d’un trou noir stellaire déchire tout bien avant.</p></div>`,
  fig:(()=>{ const P=plane({x:[-4,4],y:[-2.2,2.2],grid:false,axes:false,w:320}); P.circ(-3.2,0,0.7,{fill:'var(--ink)',fo:1,c:'var(--ink)'}); P.text(-3.2,-1.0,'trou noir',{a:'middle',dy:8,s:11,c:'var(--muted)'});
    P.poly([[0.6,0.5],[2.4,0.5],[2.4,-0.5],[0.6,-0.5]],{fill:'var(--sci)',fo:.4,c:'var(--sci)',w:2});
    vec(P,0.6,0,-0.9,0,'var(--bad)','forte',{dx:-40,dy:-8}); vec(P,2.4,0,3.3,0,'var(--muted)','',{}); P.text(3.0,0,'faible',{dy:-8,s:11,c:'var(--muted)'});
    P.text(1.5,0,'pieds   tête',{a:'middle',dy:4,s:11}); vec(P,1.5,0.5,1.5,1.5,'var(--bad)','',{w:1.5,hs:8}); vec(P,1.5,-0.5,1.5,-1.5,'var(--bad)','',{w:1.5,hs:8});
    P.text(1.5,1.5,'compression',{a:'middle',dy:-6,s:11,c:'var(--bad)'}); P.text(0,-1.8,'étirement radial, compression latérale',{a:'middle',s:11,c:'var(--muted)'}); return P.svg(); })(),
  note:'Les flèches rouges latérales pointent vers le centre du corps : les côtés sont attirés vers l’axe trou noir–corps, d’où la compression.'},
 {kind:'Méthode',h:'Estimer l’étirement de marée',p:`<p><b>Quand</b> : on demande si un objet (astronaute, étoile, sonde) survit à l’approche d’un trou noir, ou à quelle distance la marée atteint une valeur donnée.</p><p><b>Pourquoi</b> : <i>Δa</i> = 2<i>G M L</i>/<i>r</i>³ donne la différence d’accélération entre les deux bouts. On la compare à un seuil : un corps humain supporte une différence de quelques dizaines de m/s² entre la tête et les pieds (ordre de grandeur de 10 <i>g</i>) ; au-delà, il se déchire.</p><p><b>Comment</b> : 1. Calcule <i>r</i><sub>s</sub> pour savoir où est l’horizon. 2. Pour une distance <i>r</i> donnée, <i>Δa</i> = 2<i>G M L</i>/<i>r</i>³. 3. Pour un seuil <i>Δa</i><sub>max</sub> donné, inverse : <i>r</i> = (2<i>G M L</i>/<i>Δa</i><sub>max</sub>)^(1/3). 4. Compare ce rayon à <i>r</i><sub>s</sub> : s’il est plus grand, la marée tue avant l’horizon ; s’il est plus petit, l’horizon se franchit intact.</p>`,
  demo:{enonce:'Un astronaute de 2,0 m tombe les pieds en avant. Calcule la différence d’accélération entre ses pieds et sa tête à l’horizon a) d’un trou noir de 10 M☉, b) de Sagittarius A* (4,0·10⁶ M☉). <i>M</i>☉ = 1,99·10³⁰ kg, <i>G</i> = 6,67·10⁻¹¹, <i>c</i> = 3,00·10⁸ m/s.',
   etapes:[
    {f:'10 M☉ : <i>r</i><sub>s</sub> = 2,95·10⁴ m, <i>G M</i> = 1,327·10²¹',w:'Les deux ingrédients : la masse et le rayon où on évalue la marée.'},
    {f:'<i>Δa</i> = 2 × 1,327·10²¹ × 2,0/(2,95·10⁴)³ = 5,31·10²¹/2,57·10¹³ ≈ 2,1·10⁸ m/s²',w:'Vingt millions de <i>g</i> entre la tête et les pieds : l’astronaute est déchiqueté très longtemps avant d’arriver là.'},
    {f:'Sgr A* : <i>r</i><sub>s</sub> = 1,18·10¹⁰ m, <i>G M</i> = 5,31·10²⁶',w:'Masse 4·10⁵ fois plus grande, mais rayon 4·10⁵ fois plus grand aussi, élevé au cube.'},
    {f:'<i>Δa</i> = 2 × 5,31·10²⁶ × 2,0/(1,18·10¹⁰)³ = 2,12·10²⁷/1,64·10³⁰ ≈ 1,3·10⁻³ m/s²',w:'Un dix-millième de <i>g</i> : rien du tout. Rapport des deux résultats : (4·10⁵)² = 1,6·10¹¹, comme prévu par la loi en 1/<i>M</i>².'},
   ],
   conclusion:'2·10⁸ m/s² contre 1·10⁻³ m/s². Pour le trou noir stellaire, le seuil de 100 m/s² est atteint à <i>r</i> = (2 × 1,327·10²¹ × 2/100)^(1/3) ≈ 3,8·10⁶ m, soit 127 <i>r</i><sub>s</sub> : la mort arrive à 3800 km du centre, très loin de l’horizon.'}},
 {h:'La limite de survie',p:'Un astronaute de 2,0 m tombe vers un trou noir de 3,0 masses solaires (<i>M</i>☉ = 1,99·10³⁰ kg, <i>G</i> = 6,67·10⁻¹¹). À quelle distance du centre la différence d’accélération entre ses pieds et sa tête atteint-elle 100 m/s²&nbsp;? Arrondis à 10 km près.',lab:'r =',unit:'km',ans:2516,tol:15,
  why:'GM = 6,67·10⁻¹¹ × 5,97·10³⁰ = 3,98·10²⁰. r³ = 2GML/Δa = 2 × 3,98·10²⁰ × 2,0/100 = 1,59·10¹⁹ m³, donc r ≈ 2,51·10⁶ m ≈ 2510 km, soit 284 r<sub>s</sub> (r<sub>s</sub> = 8,85 km).'},
 {h:'Les orbites proches',p:`<p>Chez Newton, on peut orbiter aussi près qu’on veut d’une masse ponctuelle : il suffit d’aller assez vite. Autour d’un trou noir, le terme supplémentaire en 1/<i>r</i>³ de la métrique de Schwarzschild change la donne à quelques <i>r</i><sub>s</sub>.</p>
<div class="prop"><p><b>Dernière orbite circulaire stable</b> : <i>r</i><sub>ISCO</sub> = 3<i>r</i><sub>s</sub> = 6<i>G M</i>/<i>c</i>². En dessous, une orbite circulaire existe encore mais est instable : la moindre perturbation fait plonger le corps. <b>Sphère de photons</b> : à <i>r</i> = 1,5<i>r</i><sub>s</sub>, la lumière elle-même peut tourner en rond (orbite instable). Plus près, aucune orbite n’est possible, même pour la lumière : tout ce qui n’a pas une poussée radiale finit dans l’horizon.</p></div>
<div class="idea"><p>Un disque de gaz qui spirale vers un trou noir (disque d’accrétion) ne peut pas rester en orbite sous 3<i>r</i><sub>s</sub> : son bord interne est là, et le gaz y plonge en moins d’un tour. L’énergie libérée par la matière qui descend du loin jusqu’à l’ISCO vaut environ 5,7 % de <i>m c</i>² (contre 0,7 % pour la fusion de l’hydrogène) : c’est pourquoi les trous noirs en train d’avaler du gaz sont les objets les plus lumineux de l’Univers, les quasars.</p></div>
<div class="why"><p>Pourquoi 3<i>r</i><sub>s</sub>&nbsp;? L’énergie effective d’une orbite contient, en plus du terme newtonien −<i>G M</i>/<i>r</i> et de la barrière centrifuge <i>L</i>²/(2<i>m</i>²<i>r</i>²), le terme relativiste −<i>G M L</i>²/(<i>m</i>²<i>c</i>²<i>r</i>³). Près du centre, ce terme attractif en 1/<i>r</i>³ l’emporte sur la barrière en 1/<i>r</i>², et le « creux » qui stabilise une orbite disparaît : on montre que cela se produit à <i>r</i> = 3<i>r</i><sub>s</sub>, où la vitesse orbitale vaut déjà <i>c</i>/2.</p></div>
<div class="ex"><p>Pour Sagittarius A*, <i>r</i><sub>ISCO</sub> = 3 × 1,18·10¹⁰ = 3,5·10¹⁰ m ≈ 0,24 ua, et la sphère de photons est à 1,8·10¹⁰ m. Pour un trou noir de 10 M☉ : ISCO à 88 km, photons à 44 km.</p></div>`,
  fig:(()=>{ const P=plane({x:[-4.4,4.4],y:[-3.6,3.6],grid:false,axes:false,w:300}); P.circ(0,0,1,{fill:'var(--ink)',fo:1,c:'var(--ink)'}); P.circ(0,0,1.5,{c:'var(--spark)',w:2,dash:true}); P.circ(0,0,3,{c:'var(--accent)',w:2.5});
    P.text(0,0,'rₛ',{a:'middle',dy:4,s:12,c:'var(--surface)'}); P.text(1.5*Math.cos(rad(45)),1.5*Math.sin(rad(45)),'1,5 rₛ : photons',{dx:4,dy:-4,s:11,c:'var(--spark)'}); P.text(3*Math.cos(rad(-45)),3*Math.sin(rad(-45)),'3 rₛ : dernière orbite stable',{dx:-50,dy:16,s:11,c:'var(--accent)'});
    P.dot(3,0,{c:'var(--accent)',r:5}); vec(P,3,0,3,1.1,'var(--accent)','v ≈ c/2',{dx:6,dy:0}); return P.svg(); })()},
 {h:'Rester en orbite',p:'Un vaisseau veut se placer sur une orbite circulaire à 2 <i>r</i><sub>s</sub> d’un trou noir, moteurs coupés. Que se passe-t-il&nbsp;?',
  opts:['Impossible : sous 3 rₛ, aucune orbite circulaire n’est stable ; la moindre perturbation le fait plonger ou s’échapper','C’est possible et stable, comme autour de n’importe quelle masse, à condition d’aller assez vite','Impossible : à 2 rₛ, même la lumière ne peut pas orbiter','Possible, mais le vaisseau doit aller plus vite que la lumière'],ans:0,
  why:'Entre 1,5 rₛ et 3 rₛ, des orbites circulaires existent mais sont instables : il faut corriger sans cesse avec les moteurs. La sphère de photons est à 1,5 rₛ, donc 2 rₛ est encore accessible à la matière, mais pas durablement.'},
 {h:'Voir un trou noir',p:`<p>Un trou noir n’émet pas de lumière, mais il se trahit de deux manières : par la matière qui tourne autour et par son ombre sur le fond lumineux.</p>
<div class="idea"><p><b>L’ombre.</b> La sphère de photons à 1,5<i>r</i><sub>s</sub> capture les rayons qui passent trop près. Un calcul sur les géodésiques de la lumière montre que tout rayon visant à moins de <i>b</i> = (3√3/2)<i>r</i><sub>s</sub> ≈ 2,6<i>r</i><sub>s</sub> du centre est avalé. Vu de loin, le trou noir apparaît comme un disque sombre de diamètre ≈ 5,2<i>r</i><sub>s</sub>, entouré d’un anneau brillant formé par le gaz chaud dont la lumière est courbée autour de lui. En 2019, le réseau de radiotélescopes Event Horizon Telescope a publié cette image pour M87*, puis en 2022 pour Sagittarius A*.</p></div>
<div class="ex"><p>M87* : <i>r</i><sub>s</sub> = 1,92·10¹³ m, ombre de 5,2 × 1,92·10¹³ ≈ 1,0·10¹⁴ m, à la distance 16,8 Mpc = 5,2·10²³ m. Angle apparent : 1,0·10¹⁴/5,2·10²³ ≈ 1,9·10⁻¹⁰ rad ≈ 40 microsecondes d’arc (1 µas = 4,85·10⁻¹² rad), la taille d’une orange sur la Lune. L’image mesurée donne 42 ± 3 µas.</p></div>
<div class="blk" data-t="Rappel"><p>Troisième loi de Kepler : pour une orbite de demi-grand axe <i>a</i> et de période <i>T</i> autour d’une masse <i>M</i> ≫ <i>m</i>, <i>T</i>² = 4π²<i>a</i>³/(<i>G M</i>), donc <b><i>M</i> = 4π²<i>a</i>³/(<i>G T</i>²)</b>.</p></div>
<div class="why"><p><b>Les étoiles.</b> Depuis les années 1990, on suit des étoiles individuelles autour de Sagittarius A*. L’étoile S2 boucle une orbite très allongée en 16,0 ans, avec un demi-grand axe de 1,0·10³ ua = 1,5·10¹⁴ m, et passe à 120 ua du centre à 7700 km/s. La troisième loi de Kepler donne alors la masse centrale ; sa compacité, et l’avance du périastre de S2 mesurée en 2020 (12′ par tour, conforme à la formule du chapitre précédent), excluent tout autre objet qu’un trou noir. Ce travail a reçu le prix Nobel 2020.</p></div>`},
 {h:'Peser Sagittarius A*',p:'L’étoile S2 tourne autour de Sagittarius A* avec une période de 16,0 ans (1 an = 3,156·10⁷ s) et un demi-grand axe de 1,50·10¹⁴ m (<i>G</i> = 6,67·10⁻¹¹, <i>M</i>☉ = 1,99·10³⁰ kg). Quelle est la masse du trou noir, en millions de masses solaires&nbsp;? Arrondis au dixième.',lab:'M =',unit:'× 10⁶ M☉',ans:3.94,tol:.08,
  why:'T = 5,05·10⁸ s. M = 4π²a³/(GT²) = 39,5 × 3,375·10⁴²/(6,67·10⁻¹¹ × 2,55·10¹⁷) = 1,33·10⁴⁴/1,70·10⁷ ≈ 7,8·10³⁶ kg, soit 3,9·10⁶ masses solaires.'},
 {h:'L’évaporation de Hawking',p:`<p>En 1974, Stephen Hawking applique la physique quantique au voisinage de l’horizon et trouve un résultat inattendu : un trou noir n’est pas tout à fait noir. Il rayonne comme un corps chauffé à une température qui ne dépend que de sa masse.</p>
<div class="thm"><p><b>Température de Hawking</b> : <b><i>T</i> = ħ<i>c</i>³/(8π<i>G M k</i><sub>B</sub>)</b>, avec ħ = 1,055·10⁻³⁴ J·s et <i>k</i><sub>B</sub> = 1,381·10⁻²³ J/K. Numériquement, <i>T</i> ≈ 6,2·10⁻⁸ K × (M☉/<i>M</i>). Plus le trou noir est <b>léger</b>, plus il est <b>chaud</b>.</p></div>
<div class="idea"><p>Image habituelle : dans le vide, des paires de particules apparaissent et disparaissent sans cesse. Si une paire naît juste à l’horizon, l’un des deux partenaires peut tomber dedans tandis que l’autre s’échappe. Vu de loin, le trou noir émet une particule, et son énergie, donc sa masse, diminue d’autant. Le trou noir s’<b>évapore</b>. La formule relie les trois grandes constantes : ħ (quantique), <i>c</i> (relativité) et <i>G</i> (gravitation), avec <i>k</i><sub>B</sub> pour passer à une température.</p></div>
<div class="ex"><p>Trou noir d’une masse solaire : <i>T</i> = 1,055·10⁻³⁴ × 2,7·10²⁵/(8π × 6,67·10⁻¹¹ × 1,99·10³⁰ × 1,381·10⁻²³) ≈ 6,2·10⁻⁸ K. C’est bien plus froid que le rayonnement fossile de l’Univers (2,7 K) : un tel trou noir absorbe plus qu’il n’émet, et grossit. Sa durée d’évaporation, proportionnelle à <i>M</i>³, serait de l’ordre de 10⁶⁷ ans. Un trou noir de 10¹¹ kg (la masse d’une petite montagne), en revanche, aurait <i>T</i> ≈ 1,2·10¹² K et s’évaporerait en quelques milliards d’années : on en cherche, sans succès pour l’instant, parmi les restes du Big Bang.</p></div>
<div class="warn"><p>Le rayonnement de Hawking n’a jamais été observé directement, et ne le sera pas pour les trous noirs astrophysiques : trop froids. Il est pourtant accepté par presque tous les physiciens, car il découle de théories bien testées par ailleurs.</p></div>`},
 {h:'Un trou noir de la masse de la Lune',p:'Quelle serait la température de Hawking d’un trou noir de la masse de la Lune, 7,35·10²² kg&nbsp;? (ħ = 1,055·10⁻³⁴ J·s, <i>k</i><sub>B</sub> = 1,381·10⁻²³ J/K, <i>G</i> = 6,67·10⁻¹¹, <i>c</i> = 3,00·10⁸ m/s.) Arrondis au centième de kelvin.',lab:'T =',unit:'K',ans:1.674,tol:.015,
  why:'T = ħc³/(8πGMk<sub>B</sub>) = 2,849·10⁻⁹/(8π × 6,67·10⁻¹¹ × 7,35·10²² × 1,381·10⁻²³) = 2,849·10⁻⁹/1,70·10⁻⁹ ≈ 1,67 K. Encore plus froid que le rayonnement fossile : il ne s’évaporerait pas aujourd’hui.'},
 {kind:'Récapitulatif',h:'Ce qu’il faut retenir',p:`<div class="keep"><ul>
<li><b>Rayon de Schwarzschild</b> <i>r</i><sub>s</sub> = 2<i>GM</i>/<i>c</i>² = 2,95 km × <i>M</i>/M☉ : 8,9 mm pour la Terre, 29,5 km pour 10 M☉, 1,2·10¹⁰ m pour Sgr A*, 128 ua pour M87*. Densité moyenne ∝ 1/<i>M</i>².</li>
<li><b>Horizon</b> : rien de spécial pour qui le franchit (temps propre fini), mais vu de loin les signaux rougissent et s’espacent sans limite (<i>f</i><sub>∞</sub> = <i>f</i><sub>e</sub>√(1 − <i>r</i><sub>s</sub>/<i>r</i>) → 0) : l’image se fige et s’éteint.</li>
<li><b>Marée</b> : <i>Δa</i> = 2<i>GML</i>/<i>r</i>³ entre les deux bouts d’un corps de longueur <i>L</i>. À l’horizon, ∝ 1/<i>M</i>² : mortelle très loin d’un trou noir stellaire, inoffensive pour un trou noir supermassif.</li>
<li><b>Orbites</b> : dernière orbite circulaire stable à 3<i>r</i><sub>s</sub> (<i>v</i> ≈ <i>c</i>/2, 5,7 % de <i>mc</i>² libérés par l’accrétion), sphère de photons à 1,5<i>r</i><sub>s</sub>, ombre de diamètre ≈ 5,2<i>r</i><sub>s</sub>.</li>
<li><b>Observations</b> : ombre de M87* (40 µas) et de Sgr A* ; étoiles comme S2, dont l’orbite donne la masse par <i>M</i> = 4π²<i>a</i>³/(<i>GT</i>²) ≈ 4·10⁶ M☉.</li>
<li><b>Hawking</b> : <i>T</i> = ħ<i>c</i>³/(8π<i>GMk</i><sub>B</sub>) ≈ 6·10⁻⁸ K (M☉/<i>M</i>). Les trous noirs astrophysiques sont plus froids que le fond à 2,7 K et ne s’évaporent pas ; durée ∝ <i>M</i>³.</li>
</ul></div>
<p>Méthodes : calculer <i>r</i><sub>s</sub> et le comparer à l’objet (rayon, R☉, ua, densité) ; estimer la marée 2<i>GML</i>/<i>r</i>³ et inverser pour une distance de survie.</p>`},
 {kind:'Problème',h:'Une Terre comprimée',
  p:'On imagine la Terre (5,97·10²⁴ kg, rayon 6,37·10⁶ m) comprimée jusqu’à devenir un trou noir. La Lune (à 3,84·10⁸ m) et les satellites continuent-ils de tourner&nbsp;? Que vaut la marée près de l’horizon, et ce trou noir s’évapore-t-il&nbsp;? Données : <i>G</i> = 6,67·10⁻¹¹, <i>c</i> = 3,00·10⁸ m/s, ħ = 1,055·10⁻³⁴ J·s, <i>k</i><sub>B</sub> = 1,381·10⁻²³ J/K, rayonnement fossile à 2,7 K.',
  parts:[
   {q:'a) Quel est le rayon de Schwarzschild de la Terre&nbsp;? Arrondis au centième de millimètre.',lab:'rₛ =',unit:'mm',ans:8.85,tol:.02,hint:'<i>r</i><sub>s</sub> = 2<i>GM</i>/<i>c</i>².',why:'r<sub>s</sub> = 2 × 6,67·10⁻¹¹ × 5,97·10²⁴/(9·10¹⁶) ≈ 8,85·10⁻³ m = 8,85 mm.'},
   {q:'b) Après la compression, l’orbite de la Lune…',opts:['se resserre : un trou noir attire plus fort','ne change pas : à 3,84·10⁸ m, soit 4·10¹⁰ rₛ, le champ est celui de Newton pour la même masse','s’élargit : la Terre comprimée perd de la masse','devient instable, car elle est sous la dernière orbite stable'],ans:1,hint:'Compare la distance Terre–Lune à <i>r</i><sub>s</sub> et à 3<i>r</i><sub>s</sub>.',why:'Loin de l’horizon (r ≫ r<sub>s</sub>), la métrique de Schwarzschild redonne la gravitation newtonienne de la masse M. La Lune est à 4·10¹⁰ r<sub>s</sub> : rien ne change pour elle, ni pour les satellites.'},
   {q:'c) Un objet de 1,0 cm de long tombe radialement et passe à <i>r</i> = 1,0 m du centre. Quelle est la différence d’accélération entre ses deux bouts&nbsp;? Donne le résultat en unités de 10¹² m/s², arrondi au dixième.',lab:'Δa =',unit:'× 10¹² m/s²',ans:7.96,tol:.05,hint:'<i>Δa</i> = 2<i>GML</i>/<i>r</i>³ avec <i>L</i> = 0,010 m et <i>r</i> = 1,0 m.',why:'GM = 3,98·10¹⁴. Δa = 2 × 3,98·10¹⁴ × 0,010/1³ ≈ 7,96·10¹² m/s². Un petit trou noir est un broyeur : la marée à l’horizon varie comme 1/M².'},
   {q:'d) Quelle est la température de Hawking de ce trou noir, en millikelvins&nbsp;? Arrondis au dixième.',lab:'T =',unit:'mK',ans:20.6,tol:.2,hint:'<i>T</i> = ħ<i>c</i>³/(8π<i>GMk</i><sub>B</sub>), ou 6,2·10⁻⁸ K × M☉/<i>M</i>.',why:'T = 2,849·10⁻⁹/(8π × 6,67·10⁻¹¹ × 5,97·10²⁴ × 1,381·10⁻²³) = 2,849·10⁻⁹/1,38·10⁻⁷ ≈ 0,0206 K = 20,6 mK.'},
   {q:'e) Plongé dans le rayonnement fossile à 2,7 K, ce trou noir…',opts:['s’évapore rapidement, car il est très petit','grossit : plus froid que le fond, il absorbe plus de rayonnement qu’il n’en émet','reste exactement à la même masse, par équilibre thermique','s’évapore lentement, en quelques milliards d’années'],ans:1,hint:'Un corps plus froid que son environnement reçoit plus d’énergie qu’il n’en rayonne.',why:'À 0,02 K, le trou noir est 130 fois plus froid que le fond cosmologique : le bilan est en sa faveur, il gagne de la masse. Il ne commencerait à s’évaporer que lorsque l’expansion aura refroidi le fond sous 0,02 K.'},
  ],
  sol:'<p><i>r</i><sub>s</sub> = 2<i>GM</i>/<i>c</i>² ≈ 8,85 mm. La Lune, à 3,84·10⁸ m, est à 4·10¹⁰ rayons de Schwarzschild : elle ne voit que la masse, pas sa taille, et son orbite est inchangée. Un trou noir n’aspire pas plus que l’astre dont il est issu.</p><p>En revanche, à 1 m du centre, la marée vaut 2<i>GML</i>/<i>r</i>³ ≈ 8·10¹² m/s² sur 1 cm : tout objet qui s’approche est déchiré. À l’horizon lui-même (8,85 mm), elle serait encore 1,4·10⁶ fois plus forte.</p><p>La température de Hawking vaut 6,2·10⁻⁸ K × (1,99·10³⁰/5,97·10²⁴) ≈ 0,021 K. C’est moins que 2,7 K : le trou noir absorbe plus de photons du fond qu’il n’en émet et grossit lentement. Seuls des trous noirs plus légers qu’environ 4,5·10²² kg (plus chauds que 2,7 K) s’évaporent aujourd’hui.</p>'},
 {kind:'Problème',h:'Plongée vers Sagittarius A*',
  p:'Une sonde est envoyée vers Sagittarius A*, de masse 4,0·10⁶ M☉ (M☉ = 1,99·10³⁰ kg). Elle se met d’abord en orbite circulaire sur la dernière orbite stable, puis descend se placer immobile (moteurs allumés) à <i>r</i> = 1,10 <i>r</i><sub>s</sub>, d’où elle émet un signal radio à 1,00 GHz vers la Terre. Données : <i>G</i> = 6,67·10⁻¹¹, <i>c</i> = 3,00·10⁸ m/s, 1 ua = 1,496·10¹¹ m.',
  parts:[
   {q:'a) À quelle distance du centre, en unités astronomiques, se trouve la dernière orbite circulaire stable&nbsp;? Arrondis au centième.',lab:'r =',unit:'ua',ans:0.237,tol:.004,hint:'<i>r</i><sub>ISCO</sub> = 3<i>r</i><sub>s</sub>, et <i>r</i><sub>s</sub> = 2,95 km × 4,0·10⁶.',why:'r<sub>s</sub> = 4,0·10⁶ × 2,95·10³ = 1,18·10¹⁰ m. 3r<sub>s</sub> = 3,54·10¹⁰ m = 0,24 ua : plus près du trou noir que Mercure du Soleil.'},
   {q:'b) Quelle est la période de cette orbite, calculée avec la troisième loi de Kepler&nbsp;? Arrondis à la minute (1 h = 3600 s).',lab:'T =',unit:'min',ans:30.2,tol:.6,hint:'<i>T</i> = 2π√(<i>r</i>³/(<i>GM</i>)) avec <i>r</i> = 3<i>r</i><sub>s</sub>. (La formule exacte de Schwarzschild donne ici la même valeur.)',why:'GM = 5,31·10²⁶. T = 2π√((3,54·10¹⁰)³/5,31·10²⁶) = 2π√(8,35·10⁴) ≈ 1815 s ≈ 30 min. Des bouffées de rayonnement de Sgr A* avec des périodes de cet ordre ont effectivement été observées.'},
   {q:'c) À quelle fréquence le signal émis à 1,00 GHz depuis <i>r</i> = 1,10 <i>r</i><sub>s</sub> est-il reçu sur Terre&nbsp;? Arrondis au mégahertz.',lab:'f∞ =',unit:'MHz',ans:301.5,tol:1.5,hint:'<i>f</i><sub>∞</sub> = <i>f</i><sub>e</sub>√(1 − <i>r</i><sub>s</sub>/<i>r</i>) avec <i>r</i><sub>s</sub>/<i>r</i> = 1/1,10.',why:'1 − 1/1,10 = 0,0909, √0,0909 = 0,3015. f<sub>∞</sub> = 1000 × 0,3015 ≈ 302 MHz : le signal a perdu 70 % de sa fréquence (z = 2,3).'},
   {q:'d) La sonde fait 4,0 m de long. Quelle différence d’accélération subit-elle entre ses deux bouts à <i>r</i> = 1,10 <i>r</i><sub>s</sub>&nbsp;? Donne le résultat en unités de 10⁻³ m/s², arrondi au dixième.',lab:'Δa =',unit:'× 10⁻³ m/s²',ans:1.94,tol:.05,hint:'<i>Δa</i> = 2<i>GML</i>/<i>r</i>³ avec <i>r</i> = 1,10 × 1,18·10¹⁰ m.',why:'r = 1,30·10¹⁰ m, r³ = 2,19·10³⁰. Δa = 2 × 5,31·10²⁶ × 4,0/2,19·10³⁰ ≈ 1,9·10⁻³ m/s² : négligeable, le trou noir est supermassif.'},
   {q:'e) Si la sonde coupe ses moteurs à 1,10 <i>r</i><sub>s</sub>, que voit-on depuis la Terre&nbsp;?',opts:['Elle franchit l’horizon et on reçoit un dernier signal au moment précis du passage','Son signal rougit et s’espace de plus en plus ; on ne la voit jamais franchir l’horizon, bien qu’elle le fasse en un temps propre fini','Elle est détruite par la marée avant d’atteindre l’horizon','Elle reste en orbite circulaire : à 1,10 rₛ, la gravité et la force centrifuge s’équilibrent'],ans:1,hint:'Relis ce que l’observateur lointain voit quand r → rₛ, et compare la marée calculée en d) au seuil de rupture.',why:'Sous 1,5 r<sub>s</sub>, aucune orbite n’existe : la sonde tombe. La marée reste minuscule (question d), donc elle arrive intacte à l’horizon et le franchit en un temps propre fini. Pour la Terre, le facteur √(1 − r<sub>s</sub>/r) tend vers 0 : les signaux s’étirent sans limite et l’image se fige puis s’éteint.'},
  ],
  sol:'<p><i>r</i><sub>s</sub> = 4,0·10⁶ × 2,95 km = 1,18·10¹⁰ m. La dernière orbite stable est à 3<i>r</i><sub>s</sub> = 3,5·10¹⁰ m = 0,24 ua, parcourue en <i>T</i> = 2π√(<i>r</i>³/<i>GM</i>) ≈ 30 min.</p><p>À 1,10 <i>r</i><sub>s</sub>, le facteur temporel vaut 1 − 1/1,10 = 0,091 et sa racine 0,30 : le signal à 1 GHz arrive à 0,30 GHz, et une horloge de bord bat à 30 % du rythme terrestre.</p><p>La marée 2<i>GML</i>/<i>r</i>³ ≈ 2·10⁻³ m/s² sur 4 m est sans danger : c’est le privilège des trous noirs supermassifs, dont l’horizon est très loin du centre. Moteurs coupés sous 1,5<i>r</i><sub>s</sub>, la sonde ne peut que tomber ; elle franchit l’horizon intacte en quelques minutes de temps propre, mais la Terre ne verra jamais ce franchissement : le rougissement et l’espacement des signaux divergent à l’approche de <i>r</i><sub>s</sub>.</p>'},
]},
/* ================= 4. ONDES GRAVITATIONNELLES ET COSMOS ================= */
{subj:'phy', sem:'rel', id:'phy-rg-ondes-cosmos', h:'Ondes gravitationnelles et Univers en expansion', p:'Des rides de l’espace-temps détectées à 10⁻¹⁸ m près, puis l’Univers entier : loi de Hubble–Lemaître, décalage cosmologique et âge de l’Univers.', steps:[
 {h:'Une déformation qui se propage',p:`<p>Si la gravitation se propage à vitesse finie, que se passe-t-il quand une masse bouge brusquement&nbsp;? La courbure autour d’elle doit se mettre à jour, et cette mise à jour voyage vers l’extérieur. Einstein l’a calculé dès 1916 : les équations admettent des solutions ondulatoires.</p>
<div class="def"><p>Une <b>onde gravitationnelle</b> est une déformation de la métrique qui se propage dans le vide à la vitesse <i>c</i>. À son passage, les distances entre objets libres oscillent : étirées dans une direction, comprimées dans la direction perpendiculaire, puis l’inverse, le tout dans le plan perpendiculaire à la propagation. C’est une onde <b>transversale</b>, comme la lumière.</p></div>
<div class="idea"><p>Une onde électromagnétique est produite par une charge qui oscille ; le rayonnement le plus simple est dipolaire. Pour la gravitation, il n’y a pas de dipôle : le centre de masse d’un système isolé ne peut pas osciller (conservation de la quantité de mouvement). Il faut une distribution de masse dont la <b>forme</b> change de façon asymétrique : deux étoiles qui tournent l’une autour de l’autre, une supernova non sphérique. Une sphère qui pulse ou une barre qui tourne sur son propre axe n’émettent rien.</p></div>
<div class="why"><p>L’effet est incroyablement faible parce que la constante de couplage de la gravitation est <i>G</i>/<i>c</i>⁴ ≈ 8·10⁻⁴⁵ en unités SI : il faut des masses stellaires accélérées à une fraction de <i>c</i> pour produire une onde détectable. En 1974, Hulse et Taylor ont observé un pulsar en orbite autour d’une autre étoile à neutrons dont la période décroît exactement au rythme prévu par la perte d’énergie en ondes gravitationnelles : première preuve, indirecte. La détection directe date du 14 septembre 2015.</p></div>`,
  fig:(()=>{ const P=plane({x:[-5.5,5.5],y:[-2.2,2.2],grid:false,axes:false,w:320}); const ring=(cx,ex,ey,c)=>{ const pts=[]; for(let i=0;i<=40;i++){ const t=2*Math.PI*i/40; pts.push([cx+ex*Math.cos(t),ey*Math.sin(t)]); } P.poly(pts,{open:true,c,w:2.5}); for(let i=0;i<8;i++){ const t=2*Math.PI*i/8; P.dot(cx+ex*Math.cos(t),ey*Math.sin(t),{c,r:4}); } };
    ring(-4,1,1,'var(--muted)'); ring(-1.3,1.3,0.77,'var(--accent)'); ring(1.3,1,1,'var(--muted)'); ring(4,0.77,1.3,'var(--accent)');
    P.text(-4,-1.6,'t = 0',{a:'middle',s:11,c:'var(--muted)'}).text(-1.3,-1.6,'T/4',{a:'middle',s:11,c:'var(--muted)'}).text(1.3,-1.6,'T/2',{a:'middle',s:11,c:'var(--muted)'}).text(4,-1.6,'3T/4',{a:'middle',s:11,c:'var(--muted)'}); return P.svg(); })(),
  note:'Un anneau de masses libres, vu de face, pendant le passage d’une onde qui arrive perpendiculairement à l’écran. Les déformations sont exagérées d’un facteur 10²⁰.'},
 {h:'Les deux polarisations',p:`<p>La lumière a deux polarisations, horizontale et verticale, séparées de 90°. L’onde gravitationnelle en a deux aussi, mais séparées de 45° seulement, parce que la déformation est une ellipse, qui revient sur elle-même par rotation d’un demi-tour.</p>
<div class="def"><p>La polarisation <b>+</b> (plus) étire selon l’axe <i>x</i> quand elle comprime selon <i>y</i>, et inversement. La polarisation <b>×</b> (croix) fait la même chose selon les diagonales. Toute onde est une combinaison des deux. Pour la polarisation +, un point à la position (<i>x</i> ; <i>y</i>) dans le plan de l’onde se déplace en <b>(<i>x</i>(1 + ½<i>h</i> cos <i>ωt</i>) ; <i>y</i>(1 − ½<i>h</i> cos <i>ωt</i>))</b>, où <i>h</i> est l’amplitude de l’onde.</p></div>
<div class="idea"><p>Le déplacement est <b>proportionnel à la distance</b> au centre : plus deux masses sont éloignées, plus leur écart oscille. C’est une déformation de l’espace, pas une force qui pousserait chaque masse de la même quantité. C’est aussi pourquoi un détecteur gagne à être long. Dans la figure, le facteur ½<i>h</i> est fixé à une valeur énorme pour qu’on voie quelque chose ; en réalité, <i>h</i> ≈ 10⁻²¹.</p></div>
<div class="why"><p>Pourquoi deux directions à la fois, et en opposition&nbsp;? Parce que l’onde ne change pas le volume au premier ordre : ce qu’elle étire dans une direction, elle le comprime dans l’autre. Une onde qui dilaterait tout dans toutes les directions reviendrait à changer la masse de la source, ce que la conservation de l’énergie interdit.</p></div>`,
  params:[{id:'ph',l:'Phase ωt',min:0,max:360,step:15,v:0,u:'°'},{id:'h',l:'Amplitude h (exagérée)',min:0,max:0.6,step:.1,v:0.4,u:''},{id:'pol',l:'Polarisation (0 : +, 1 : ×)',min:0,max:1,step:1,v:0,u:''}],
  draw:v=>{ const P=plane({x:[-2.2,2.2],y:[-2.2,2.2],grid:true,step:1,w:260}); const s=0.5*v.h*Math.cos(rad(v.ph)), th=v.pol?Math.PI/4:0, c=Math.cos(th), sn=Math.sin(th);
    const map=(x,y)=>{ const u=x*c+y*sn, w=-x*sn+y*c; const u2=u*(1+s), w2=w*(1-s); return [u2*c-w2*sn,u2*sn+w2*c]; };
    const pts=[]; for(let i=0;i<=48;i++){ const t=2*Math.PI*i/48; pts.push(map(1.5*Math.cos(t),1.5*Math.sin(t))); } P.poly(pts,{open:true,c:'var(--line)',w:1.5,dash:true});
    P.circ(0,0,1.5,{c:'var(--muted)',w:1,dash:true}); for(let i=0;i<12;i++){ const t=2*Math.PI*i/12, q=map(1.5*Math.cos(t),1.5*Math.sin(t)); P.dot(q[0],q[1],{c:v.pol?'var(--math)':'var(--accent)',r:5}); }
    return P.svg(); },
  info:v=>`Polarisation ${v.pol?'×':'+'} · ½<i>h</i> cos <i>ωt</i> = ${fmt(0.5*v.h*Math.cos(rad(v.ph)),3)} · un point à 1,5 m de l’axe ${v.pol?'diagonal':'horizontal'} est déplacé de ${fmt(Math.abs(1.5*0.5*v.h*Math.cos(rad(v.ph))),3)} m`,
  note:'Le cercle pointillé fin est la position au repos. Balaye la phase : l’ellipse bascule d’un quart de période à l’autre.'},
 {h:'L’amplitude h et la variation de longueur',p:`<p>Comment mesurer une onde gravitationnelle&nbsp;? Avec deux masses libres à la distance <i>L</i> et une règle pour mesurer leur écart. L’onde change cet écart, et la règle qui ne change pas, c’est la lumière : on mesure le temps d’aller-retour d’un faisceau laser.</p>
<div class="def"><p>L’<b>amplitude</b> <i>h</i> d’une onde gravitationnelle (sans unité, on dit « déformation » ou <i>strain</i>) est définie par la variation relative de longueur qu’elle produit entre deux masses libres : <b><i>ΔL</i> = ½ <i>h L</i></b>, où <i>L</i> est la distance au repos le long de l’axe d’étirement. Le facteur ½ vient de la formule de la polarisation : <i>x</i>(1 + ½<i>h</i>).</p></div>
<div class="ex"><p>Les détecteurs LIGO ont deux bras perpendiculaires de <i>L</i> = 4 km. Pour le premier signal détecté, <i>h</i> ≈ 1·10⁻²¹ au maximum : <i>ΔL</i> = ½ × 10⁻²¹ × 4000 = 2·10⁻¹⁸ m. Un proton mesure 10⁻¹⁵ m : la variation de longueur est <b>cinq cents fois plus petite qu’un proton</b>, sur une distance de 4 km. Et comme un bras s’allonge quand l’autre raccourcit, la différence de longueur entre les bras varie de 2<i>ΔL</i> = 4·10⁻¹⁸ m.</p></div>
<div class="idea"><p>Un interféromètre compare la lumière revenue des deux bras : si les longueurs diffèrent d’une fraction de longueur d’onde, l’intensité en sortie change. Pour descendre à 10⁻¹⁸ m avec un laser à 10⁻⁶ m, il faut faire rebondir la lumière environ 300 fois dans chaque bras, utiliser des miroirs de 40 kg suspendus à des pendules multiples, un vide poussé, et des lasers de forte puissance pour réduire le bruit statistique des photons. Il a fallu quarante ans pour y arriver.</p></div>
<div class="warn"><p>L’onde n’étire pas la lumière en même temps que le bras&nbsp;? Si, mais le nombre de longueurs d’onde contenues dans le bras change quand même, parce que la lumière qui circule a été émise avant la déformation : le temps d’aller-retour, mesuré par une horloge locale, change bien de 2<i>ΔL</i>/<i>c</i>.</p></div>`},
 {kind:'Méthode',h:'Passer de l’amplitude h à la variation de longueur, et retour',p:`<p><b>Quand</b> : on connaît <i>h</i> et la longueur d’un détecteur et on demande le déplacement à mesurer, ou on connaît la sensibilité en longueur et on demande quelle amplitude est détectable.</p><p><b>Pourquoi</b> : <i>ΔL</i> = ½<i>h L</i> est linéaire. Allonger le détecteur augmente le signal dans le même rapport, ce qui justifie des bras kilométriques sur Terre et des millions de kilomètres dans l’espace.</p><p><b>Comment</b> : 1. Identifie <i>L</i> (longueur d’un bras, pas l’aller-retour). 2. <i>ΔL</i> = ½<i>h L</i>, en mètres ; convertis ensuite dans une unité parlante (attomètre 10⁻¹⁸ m, taille d’un proton 10⁻¹⁵ m). 3. Dans l’autre sens, <i>h</i> = 2<i>ΔL</i>/<i>L</i>. 4. Pour la différence entre les deux bras perpendiculaires d’un interféromètre, double le résultat.</p>`,
  demo:{enonce:'a) Une onde d’amplitude <i>h</i> = 1,0·10⁻²¹ traverse LIGO (bras de 4,0 km). De combien un bras change-t-il de longueur&nbsp;? b) Le détecteur Virgo (bras de 3,0 km) mesure des déplacements jusqu’à 1,0·10⁻¹⁸ m. Quelle est la plus petite amplitude qu’il détecte&nbsp;?',
   etapes:[
    {f:'<i>ΔL</i> = ½ × 1,0·10⁻²¹ × 4,0·10³ = 2,0·10⁻¹⁸ m',w:'Un demi, puis l’amplitude, puis la longueur d’un bras en mètres.'},
    {f:'Soit 2 attomètres, le cinq-centième du rayon d’un proton. Différence entre les deux bras : 4,0·10⁻¹⁸ m',w:'L’interféromètre est sensible à la différence, et les deux bras bougent en sens contraires.'},
    {f:'<i>h</i><sub>min</sub> = 2<i>ΔL</i>/<i>L</i> = 2 × 1,0·10⁻¹⁸/3,0·10³ ≈ 6,7·10⁻²²',w:'On retourne la formule. Plus le bras est long, plus <i>h</i><sub>min</sub> est petit à <i>ΔL</i> égal.'},
   ],
   conclusion:'2,0·10⁻¹⁸ m pour LIGO ; 6,7·10⁻²² pour Virgo. Le futur détecteur spatial LISA aura des bras de 2,5 millions de kilomètres : à <i>h</i> égal, le déplacement est 600 000 fois plus grand, ce qui permet de viser des ondes de très basse fréquence.'}},
 {h:'Les bras de LISA',p:'Le détecteur spatial LISA aura des bras de 2,5·10⁹ m. Une onde d’amplitude <i>h</i> = 1,0·10⁻²⁰ le traverse. De combien varie la longueur d’un bras&nbsp;? Donne la réponse en picomètres (1 pm = 10⁻¹² m), arrondie au dixième.',lab:'ΔL =',unit:'pm',ans:12.5,tol:.1,
  why:'ΔL = ½hL = ½ × 10⁻²⁰ × 2,5·10⁹ = 1,25·10⁻¹¹ m = 12,5 pm : un dixième de la taille d’un atome, sur 2,5 millions de kilomètres.'},
 {h:'Le chirp : la fréquence qui monte',p:`<p>Le signal détecté le 14 septembre 2015 (GW150914) dure 0,2 s. Sa fréquence monte de 35 Hz à 250 Hz tandis que son amplitude grandit, puis tout s’arrête : c’est un <b>chirp</b>, un « gazouillis », la signature de deux corps compacts qui spiralent l’un vers l’autre et fusionnent.</p>
<div class="idea"><p>Deux masses en orbite émettent des ondes gravitationnelles, donc perdent de l’énergie, donc se rapprochent (une orbite plus serrée a une énergie plus basse). Plus elles sont proches, plus elles tournent vite, et plus elles rayonnent : l’emballement se termine par la fusion. La fréquence de l’onde est le <b>double</b> de la fréquence orbitale, parce que la configuration des deux masses se répète tous les demi-tours (la forme du système, pas sa position, détermine l’onde).</p></div>
<div class="blk" data-t="Rappel"><p>Troisième loi de Kepler pour deux masses <i>M</i>₁ et <i>M</i>₂ séparées de <i>r</i>, avec <i>M</i> = <i>M</i>₁ + <i>M</i>₂ et <i>ω</i> = 2π<i>f</i><sub>orb</sub> : <i>ω</i>² <i>r</i>³ = <i>G M</i>, donc <b><i>r</i> = (<i>G M</i>/<i>ω</i>²)^(1/3)</b>.</p></div>
<div class="ex"><p>Au pic de GW150914, <i>f</i><sub>onde</sub> = 150 Hz, donc <i>f</i><sub>orb</sub> = 75 Hz et <i>ω</i> = 471 rad/s. Pour une masse totale de 65 M☉ (<i>G M</i> = 8,63·10²¹) : <i>r</i> = (8,63·10²¹/2,22·10⁵)^(1/3) = (3,89·10¹⁶)^(1/3) ≈ 3,4·10⁵ m = 340 km. Or le rayon de Schwarzschild de 65 M☉ vaut 192 km : les deux objets ne sont séparés que de moins de deux <i>r</i><sub>s</sub> en tournant 75 fois par seconde. Seuls des trous noirs sont assez compacts pour cela ; des étoiles à neutrons de 12 km se seraient déjà touchées bien avant, et des étoiles ordinaires auraient fusionné à des fréquences mille fois plus basses.</p></div>
<div class="why"><p>La vitesse à laquelle la fréquence monte, d<i>f</i>/d<i>t</i>, dépend des masses par une combinaison appelée <b>masse de chirp</b> ℳ = (<i>M</i>₁<i>M</i>₂)^(3/5)/(<i>M</i>₁ + <i>M</i>₂)^(1/5) : plus les masses sont grandes, plus l’énergie rayonnée est forte et plus le chirp est rapide. On lit donc la masse du système sur la forme du signal, et l’amplitude reçue donne ensuite la distance : 1,3 milliard d’années-lumière pour GW150914.</p></div>`,
  fig:(()=>{ const P=plane({x:[-0.22,0.03],y:[-1.3,1.3],grid:false,axes:false,w:320,h:150}); const tc=0.0, f=t=>Math.min(250,35*Math.pow(0.2/Math.max(tc-t,0.004),3/8)), A=t=>Math.min(1,0.25*Math.pow(0.2/Math.max(tc-t,0.004),1/4));
    let ph=0, pts=[]; const n=1200; for(let i=0;i<=n;i++){ const t=-0.2+0.2*i/n; ph+=2*Math.PI*f(t)*0.2/n; pts.push([t,A(t)*Math.sin(ph)*(t<-0.002?1:Math.exp(-(t+0.002)/0.004))]); }
    P.poly(pts,{open:true,c:'var(--accent)',w:2}); P.seg(-0.22,0,0.03,0,{c:'var(--line)',w:1}); P.text(-0.2,1.1,'35 Hz',{s:11,c:'var(--muted)'}).text(-0.01,1.1,'250 Hz',{a:'end',s:11,c:'var(--muted)'}).text(-0.1,-1.2,'0,2 s',{a:'middle',s:11,c:'var(--muted)'}); return P.svg(); })(),
  note:'Allure du signal : la fréquence et l’amplitude montent ensemble jusqu’à la fusion, puis le trou noir final « sonne » brièvement et se tait.'},
 {h:'La séparation au moment du signal',p:'Deux trous noirs de masse totale 30 M☉ (M☉ = 1,99·10³⁰ kg, <i>G</i> = 6,67·10⁻¹¹) émettent une onde gravitationnelle à 200 Hz. Quelle est leur séparation à cet instant, d’après la troisième loi de Kepler&nbsp;? Arrondis à 1 km.',lab:'r =',unit:'km',ans:216,tol:2,
  why:'f<sub>orb</sub> = 100 Hz, ω = 2π × 100 = 628 rad/s, ω² = 3,95·10⁵. GM = 30 × 1,99·10³⁰ × 6,67·10⁻¹¹ = 3,98·10²¹. r = (3,98·10²¹/3,95·10⁵)^(1/3) = (1,01·10¹⁶)^(1/3) ≈ 2,16·10⁵ m = 216 km, soit 2,4 fois le rayon de Schwarzschild de 30 M☉ (88 km).'},
 {h:'L’énergie rayonnée',p:`<p>Combien d’énergie une fusion de trous noirs emporte-t-elle en ondes gravitationnelles&nbsp;? La réponse vient du bilan de masse.</p>
<div class="blk" data-t="Rappel"><p>Relativité restreinte : toute énergie <i>E</i> possède une masse <i>E</i>/<i>c</i>², et une perte de masse <i>Δm</i> libère l’énergie <i>E</i> = <i>Δm c</i>².</p></div>
<div class="ex"><p>GW150914 : deux trous noirs de 36 et 29 M☉ ont donné un trou noir final de 62 M☉. La différence, 3 M☉, est partie en ondes gravitationnelles : <i>E</i> = 3 × 1,99·10³⁰ × (3·10⁸)² ≈ 5,4·10⁴⁷ J. Émise en 0,2 s environ, cela fait une puissance de 2,7·10⁴⁸ W, à comparer aux 3,8·10²⁶ W du Soleil : pendant un cinquième de seconde, ce système a rayonné plus que toutes les étoiles de l’Univers observable réunies (environ 10²² soleils).</p></div>
<div class="idea"><p>Pourquoi n’a-t-on rien vu&nbsp;? Parce que cette énergie est dans la géométrie, pas dans la lumière : l’espace-temps est extraordinairement rigide, et une énergie colossale ne le déforme que de <i>h</i> ≈ 10⁻²¹ à 1,3 milliard d’années-lumière. La rigidité se lit dans le facteur <i>c</i>⁴/<i>G</i> ≈ 10⁴⁴ N qui relie courbure et énergie.</p></div>
<div class="why"><p>L’amplitude décroît comme 1/<i>d</i> (et non 1/<i>d</i>² comme l’intensité lumineuse, parce que les détecteurs mesurent l’amplitude et non la puissance). Doubler la sensibilité des détecteurs double donc la distance accessible et multiplie par huit le volume d’Univers observé, donc le nombre d’événements. C’est pourquoi chaque amélioration des instruments fait bondir le nombre de détections : une poignée en 2015, plus de deux cents aujourd’hui.</p></div>`},
 {h:'La fusion d’étoiles à neutrons',p:'Lors de la fusion de deux étoiles à neutrons observée en 2017, l’équivalent de 0,025 masse solaire (M☉ = 1,99·10³⁰ kg, <i>c</i> = 3,00·10⁸ m/s) a été rayonné en ondes gravitationnelles. Quelle énergie cela représente-t-il&nbsp;? Donne la réponse en unités de 10⁴⁵ J, arrondie au dixième.',lab:'E =',unit:'× 10⁴⁵ J',ans:4.48,tol:.05,
  why:'E = Δm c² = 0,025 × 1,99·10³⁰ × 9·10¹⁶ ≈ 4,48·10⁴⁵ J. C’est 120 fois moins que GW150914, mais la fusion a aussi produit de la lumière, observée par des dizaines de télescopes : première observation « multi-messager ».'},
 {h:'La loi de Hubble–Lemaître',p:`<p>Changeons d’échelle : l’Univers entier. Dans les années 1920, Vesto Slipher puis Edwin Hubble mesurent les spectres de galaxies : presque toutes ont leurs raies décalées vers le rouge, et d’autant plus qu’elles sont lointaines. Georges Lemaître, en 1927, relie ce fait aux solutions des équations d’Einstein pour un Univers en expansion.</p>
<div class="thm"><p><b>Loi de Hubble–Lemaître.</b> Une galaxie à la distance <i>d</i> s’éloigne de nous à la vitesse <b><i>v</i> = <i>H</i>₀ <i>d</i></b>. La <b>constante de Hubble</b> vaut <i>H</i>₀ ≈ 70 km/s par mégaparsec (1 Mpc = 3,26 millions d’années-lumière = 3,09·10²² m), soit en unités SI <i>H</i>₀ = 7,0·10⁴/3,09·10²² ≈ 2,27·10⁻¹⁸ s⁻¹.</p></div>
<div class="idea"><p>La loi est la même vue de n’importe quelle galaxie. Pense à des points dessinés sur un ballon qu’on gonfle, ou à des raisins dans un cake qui lève : chaque raisin voit tous les autres s’éloigner, et deux fois plus vite s’ils sont deux fois plus loin, sans qu’aucun soit au centre. Une vitesse proportionnelle à la distance est exactement ce que produit une <b>dilatation uniforme</b>. L’Univers n’a pas de centre d’expansion.</p></div>
<div class="ex"><p>Une galaxie à 100 Mpc (326 millions d’années-lumière) s’éloigne à <i>v</i> = 70 × 100 = 7000 km/s, soit 2,3 % de <i>c</i>. À 1 Mpc, la vitesse d’expansion n’est que de 70 km/s, moins que les mouvements propres des galaxies dans leur amas : la loi ne se voit clairement qu’au-delà de quelques dizaines de mégaparsecs. La valeur de <i>H</i>₀ est encore discutée entre 67 et 73 km/s/Mpc selon la méthode de mesure.</p></div>`,
  params:[{id:'H',l:'H₀',min:50,max:90,step:5,v:70,u:' km/s/Mpc'},{id:'d',l:'Distance d',min:0,max:500,step:25,v:200,u:' Mpc'}],
  draw:v=>{ const P=plane({x:[-40,540],y:[-4000,48000],grid:true,step:100,lab:100,w:320,h:210}); for(const y of [10000,20000,30000,40000]) P.text(-5,y,fmt(y/1000,0)+'k',{a:'end',s:10,c:'var(--muted)',dy:4});
    P.fn(x=>v.H*x,{from:0,to:540,c:'var(--accent)'}); P.seg(v.d,0,v.d,v.H*v.d,{c:'var(--muted)',w:1,dash:true}).seg(0,v.H*v.d,v.d,v.H*v.d,{c:'var(--muted)',w:1,dash:true});
    P.dot(v.d,v.H*v.d,{l:fmt(v.H*v.d,0)+' km/s'}); P.text(530,0,'d (Mpc)',{a:'end',dy:16,s:11,c:'var(--muted)'}).text(0,46000,'v (km/s)',{dx:4,s:11,c:'var(--muted)'}); return P.svg(); },
  info:v=>`<i>v</i> = <i>H</i>₀ <i>d</i> = ${v.H} × ${v.d} = ${fmt(v.H*v.d,0)} km/s, soit ${fmt(v.H*v.d/3e5*100,1)} % de <i>c</i> · <i>z</i> ≈ <i>v</i>/<i>c</i> = ${fmt(v.H*v.d/3e5,3)}`,
  note:'La pente de la droite est H₀. Une galaxie à 500 Mpc fuit à plus de 10 % de c : au-delà, l’approximation z ≈ v/c cesse d’être valable.'},
 {h:'Le décalage cosmologique',p:`<p>On présente souvent le décalage des galaxies comme un effet Doppler : elles fuient, donc leur lumière rougit. C’est correct pour les galaxies proches, mais la relativité générale en donne une image plus juste et plus simple.</p>
<div class="def"><p>Le <b>décalage vers le rouge</b> <i>z</i> d’une raie émise à <i>λ</i><sub>e</sub> et reçue à <i>λ</i><sub>obs</sub> est défini par <b>1 + <i>z</i> = <i>λ</i><sub>obs</sub>/<i>λ</i><sub>e</sub></b>. En cosmologie, 1 + <i>z</i> est aussi le <b>facteur d’étirement de l’Univers</b> entre l’émission et la réception : si les distances ont doublé pendant le trajet de la lumière, <i>z</i> = 1.</p></div>
<div class="idea"><p>La lumière voyage pendant des millions d’années dans un espace qui se dilate. Sa longueur d’onde est une distance comme une autre : elle est étirée dans le même rapport que l’espace. Ce n’est pas la galaxie qui court dans l’espace en s’éloignant de nous ; c’est l’espace entre elle et nous qui grandit. Les galaxies restent à peu près immobiles dans leur voisinage, comme les raisins dans le cake.</p></div>
<div class="prop"><p>Pour <i>z</i> ≪ 1, les deux images coïncident : <b><i>v</i> ≈ <i>c z</i></b>, donc <i>d</i> ≈ <i>c z</i>/<i>H</i>₀. Pour <i>z</i> grand, « vitesse » et « distance » deviennent ambigus (distance à quel moment&nbsp;?), et seule l’interprétation géométrique tient : les galaxies les plus lointaines observées ont <i>z</i> ≈ 13, leur lumière a été émise quand l’Univers était 14 fois plus petit.</p></div>
<div class="warn"><p>Les galaxies ne s’éloignent pas « plus vite que la lumière » au sens de la relativité restreinte quand <i>H</i>₀<i>d</i> dépasse <i>c</i> : aucune information ne dépasse <i>c</i> localement. C’est la croissance de l’espace entre elles et nous qui n’est pas limitée. Le rayonnement fossile, émis à <i>z</i> ≈ 1100, nous parvient de régions qui « s’éloignent » à plusieurs fois <i>c</i>.</p></div>`},
 {kind:'Méthode',h:'De la raie décalée à la distance',p:`<p><b>Quand</b> : on mesure dans le spectre d’une galaxie une raie connue (hydrogène Hα à 656,3 nm, oxygène à 500,7 nm…) à une longueur d’onde différente de sa valeur au laboratoire, et on demande la vitesse de fuite et la distance. Valable tant que <i>z</i> reste petit (quelques centièmes).</p><p><b>Pourquoi</b> : 1 + <i>z</i> = <i>λ</i><sub>obs</sub>/<i>λ</i><sub>e</sub> donne <i>z</i> ; pour <i>z</i> ≪ 1, <i>v</i> ≈ <i>c z</i> ; puis la loi de Hubble–Lemaître donne <i>d</i> = <i>v</i>/<i>H</i>₀.</p><p><b>Comment</b> : 1. <i>z</i> = <i>λ</i><sub>obs</sub>/<i>λ</i><sub>e</sub> − 1 (sans unité ; vérifie que c’est positif pour un décalage vers le rouge). 2. <i>v</i> = <i>c z</i>, en km/s si tu prends <i>c</i> = 3,00·10⁵ km/s. 3. <i>d</i> = <i>v</i>/<i>H</i>₀ en Mpc si <i>v</i> est en km/s et <i>H</i>₀ en km/s/Mpc. 4. Au besoin, 1 Mpc = 3,09·10²² m = 3,26·10⁶ années-lumière.</p>`,
  demo:{enonce:'Dans le spectre d’une galaxie, la raie Hα de l’hydrogène (656,3 nm au laboratoire) est observée à 672,7 nm. Calcule son décalage <i>z</i>, sa vitesse de fuite et sa distance (<i>H</i>₀ = 70 km/s/Mpc).',
   etapes:[
    {f:'<i>z</i> = 672,7/656,3 − 1 ≈ 0,0250',w:'Le rapport des longueurs d’onde ; 2,5 % d’étirement.'},
    {f:'<i>v</i> ≈ <i>c z</i> = 3,00·10⁵ × 0,0250 ≈ 7500 km/s',w:'<i>z</i> est petit, l’approximation est bonne à 1 % près.'},
    {f:'<i>d</i> = <i>v</i>/<i>H</i>₀ = 7500/70 ≈ 107 Mpc',w:'Les unités s’arrangent : km/s divisé par km/s/Mpc donne des Mpc.'},
    {f:'Soit 107 × 3,26·10⁶ ≈ 3,5·10⁸ années-lumière, ou 3,3·10²⁴ m',w:'La lumière reçue a été émise il y a environ 350 millions d’années.'},
   ],
   conclusion:'<i>z</i> = 0,025, <i>v</i> ≈ 7500 km/s, <i>d</i> ≈ 107 Mpc. L’incertitude sur <i>H</i>₀ (67 à 73) se reporte directement sur la distance : c’est l’enjeu de la « tension de Hubble ».'}},
 {h:'La raie de l’oxygène',p:'La raie de l’oxygène à 500,7 nm est observée à 515,7 nm dans le spectre d’une galaxie. Quelle est sa distance, avec <i>H</i>₀ = 70 km/s/Mpc et <i>c</i> = 3,00·10⁵ km/s&nbsp;? Arrondis au mégaparsec.',lab:'d =',unit:'Mpc',ans:128.4,tol:1,
  why:'z = 515,7/500,7 − 1 ≈ 0,0300, v = cz ≈ 8990 km/s, d = 8990/70 ≈ 128 Mpc.'},
 {h:'L’âge de l’Univers',p:`<p>Si tout s’éloigne de tout, c’est que tout était plus proche autrefois. En remontant le temps, les distances tendent vers zéro : il y a eu un commencement de l’expansion, le Big Bang. La loi de Hubble–Lemaître permet d’en estimer la date.</p>
<div class="idea"><p>Suppose la vitesse de chaque galaxie constante au cours du temps. Une galaxie aujourd’hui à la distance <i>d</i>, qui s’éloigne à <i>v</i> = <i>H</i>₀<i>d</i>, était à distance nulle il y a <i>t</i> = <i>d</i>/<i>v</i> = <b>1/<i>H</i>₀</b>. Le résultat ne dépend pas de la galaxie choisie : toutes étaient « ici » au même instant. C’est le <b>temps de Hubble</b>.</p></div>
<div class="ex"><p><i>H</i>₀ = 70 km/s/Mpc = 7,0·10⁴ m/s / 3,09·10²² m = 2,27·10⁻¹⁸ s⁻¹. Donc 1/<i>H</i>₀ = 4,41·10¹⁷ s. Avec 1 an = 3,156·10⁷ s : 4,41·10¹⁷/3,156·10⁷ ≈ 1,40·10¹⁰ ans, soit <b>14 milliards d’années</b>. L’âge précis, obtenu en tenant compte des variations du rythme d’expansion (freinage par la matière, puis accélération), est de 13,8 milliards d’années : le temps de Hubble donne le bon ordre de grandeur.</p></div>
<div class="why"><p>En relativité générale, le rythme d’expansion n’est pas constant : la gravitation de la matière le freine, et l’énergie sombre l’accélère depuis quelques milliards d’années. Les deux effets se compensent à peu près aujourd’hui, d’où la coïncidence. Ce qui s’étire, c’est l’espace lui-même : l’expansion n’a pas de centre, pas de bord, et ne se produit pas « dans » un espace préexistant. Les atomes, les étoiles, les galaxies liées par la gravitation ne s’étirent pas : seules les distances entre structures indépendantes grandissent.</p></div>
<div class="warn"><p>Une vieille étoile ne peut pas être plus âgée que l’Univers. Les plus vieux amas d’étoiles ont 12 à 13 milliards d’années : compatible avec 13,8, et c’est un test réussi. Avec <i>H</i>₀ = 100 km/s/Mpc, valeur défendue jusque dans les années 1990, 1/<i>H</i>₀ ne ferait que 9,8 milliards d’années et il y aurait contradiction.</p></div>`},
 {h:'Ce qui s’étire et ce qui ne s’étire pas',p:'Laquelle de ces affirmations décrit correctement l’expansion de l’Univers selon la relativité générale&nbsp;?',
  opts:['Les galaxies s’éloignent d’un centre, le lieu du Big Bang, en se déplaçant dans un espace fixe','Tout grandit dans les mêmes proportions : les galaxies, le système solaire et les atomes aussi','C’est l’espace entre les galaxies qui s’étire ; aucune galaxie n’est au centre, et les systèmes liés par la gravitation gardent leur taille','La Voie lactée est immobile au centre, puisque toutes les galaxies s’éloignent d’elle'],ans:2,
  why:'La loi v = H₀d est la même vue de n’importe quelle galaxie : il n’y a pas de centre. Les longueurs d’onde en transit s’étirent avec l’espace, mais les atomes et les systèmes liés résistent à cet étirement et gardent leur taille. Sinon, nos règles s’allongeraient aussi et nous ne mesurerions rien.'},
 {kind:'Récapitulatif',h:'Ce qu’il faut retenir',p:`<div class="keep"><ul>
<li><b>Onde gravitationnelle</b> : déformation transversale de la métrique qui se propage à <i>c</i>, émise par une masse dont la forme change de façon asymétrique (deux corps en orbite). Deux polarisations, + et ×, à 45° l’une de l’autre ; étirement dans une direction, compression dans l’autre.</li>
<li><b>Amplitude</b> <i>h</i> : <i>ΔL</i> = ½<i>hL</i>. LIGO : <i>h</i> ≈ 10⁻²¹ sur 4 km → 2·10⁻¹⁸ m, le cinq-centième d’un proton. <i>h</i> décroît en 1/<i>d</i>.</li>
<li><b>Chirp</b> : fréquence et amplitude montent jusqu’à la fusion ; <i>f</i><sub>onde</sub> = 2<i>f</i><sub>orb</sub> ; Kepler donne la séparation <i>r</i> = (<i>GM</i>/<i>ω</i>²)^(1/3) (340 km à 150 Hz pour 65 M☉). La masse se lit sur la vitesse du chirp.</li>
<li><b>Énergie rayonnée</b> : <i>E</i> = <i>Δm c</i>² ; 3 M☉ → 5,4·10⁴⁷ J en 0,2 s pour GW150914, plus que toutes les étoiles visibles.</li>
<li><b>Hubble–Lemaître</b> : <i>v</i> = <i>H</i>₀<i>d</i>, <i>H</i>₀ ≈ 70 km/s/Mpc = 2,27·10⁻¹⁸ s⁻¹ (1 Mpc = 3,09·10²² m). Dilatation uniforme, sans centre.</li>
<li><b>Décalage cosmologique</b> : 1 + <i>z</i> = <i>λ</i><sub>obs</sub>/<i>λ</i><sub>e</sub> = facteur d’étirement de l’Univers depuis l’émission. Pour <i>z</i> ≪ 1 : <i>v</i> ≈ <i>cz</i>, <i>d</i> ≈ <i>cz</i>/<i>H</i>₀.</li>
<li><b>Âge</b> : temps de Hubble 1/<i>H</i>₀ ≈ 4,4·10¹⁷ s ≈ 14 milliards d’années (valeur précise 13,8). C’est l’espace qui s’étire ; les systèmes liés gardent leur taille.</li>
</ul></div>
<p>Méthodes : passer de <i>h</i> à <i>ΔL</i> et retour (doubler pour la différence entre deux bras) ; d’une raie décalée à <i>z</i>, <i>v</i> = <i>cz</i>, puis <i>d</i> = <i>v</i>/<i>H</i>₀.</p>`},
 {kind:'Problème',h:'GW150914 en chiffres',
  p:'Le premier signal d’ondes gravitationnelles provenait de deux trous noirs de 36 et 29 M☉ qui ont fusionné en un trou noir de 62 M☉, à 1,3 milliard d’années-lumière. L’amplitude maximale reçue valait <i>h</i> = 1,0·10⁻²¹, à une fréquence d’onde de 150 Hz ; l’essentiel de l’énergie est parti en 0,20 s. Données : M☉ = 1,99·10³⁰ kg, <i>G</i> = 6,67·10⁻¹¹, <i>c</i> = 3,00·10⁸ m/s, luminosité du Soleil 3,8·10²⁶ W.',
  parts:[
   {q:'a) De combien la différence de longueur entre les deux bras de 4,0 km de LIGO a-t-elle varié au maximum&nbsp;? Donne le résultat en unités de 10⁻¹⁸ m.',lab:'δ =',unit:'× 10⁻¹⁸ m',ans:4,tol:.05,hint:'Un bras s’allonge de ½<i>hL</i> pendant que l’autre raccourcit d’autant.',why:'ΔL = ½ × 10⁻²¹ × 4000 = 2·10⁻¹⁸ m par bras, en sens contraires : différence 4·10⁻¹⁸ m.'},
   {q:'b) Quelle était la séparation des deux trous noirs quand l’onde était à 150 Hz, d’après la troisième loi de Kepler (masse totale 65 M☉)&nbsp;? Arrondis à 10 km.',lab:'r =',unit:'km',ans:339,tol:6,hint:'<i>f</i><sub>orb</sub> = 75 Hz, <i>ω</i> = 2π<i>f</i><sub>orb</sub>, <i>r</i> = (<i>GM</i>/<i>ω</i>²)^(1/3).',why:'GM = 65 × 1,99·10³⁰ × 6,67·10⁻¹¹ = 8,63·10²¹. ω = 471 rad/s, ω² = 2,22·10⁵. r = (3,89·10¹⁶)^(1/3) ≈ 3,4·10⁵ m = 340 km.'},
   {q:'c) Compare cette séparation au rayon de Schwarzschild de la masse totale. Que conclut-on&nbsp;?',opts:['r ≈ 1,8 rₛ : les deux objets sont à moins de deux rayons de Schwarzschild, seuls des trous noirs sont assez compacts','r ≈ 18 rₛ : des étoiles à neutrons ou des naines blanches pourraient aussi convenir','r ≈ 0,5 rₛ : ils ont déjà fusionné, le signal vient de l’intérieur de l’horizon','r ≈ 180 rₛ : n’importe quel couple d’étoiles ferait l’affaire'],ans:0,hint:'<i>r</i><sub>s</sub>(65 M☉) = 65 × 2,95 km.',why:'r<sub>s</sub> = 65 × 2,95 ≈ 192 km, donc r/r<sub>s</sub> ≈ 1,8. Deux objets de 30 M☉ séparés de 340 km et tournant 75 fois par seconde ne peuvent être que des trous noirs : des étoiles à neutrons de cette masse n’existent pas, et tout autre astre serait bien plus grand que 340 km.'},
   {q:'d) Quelle énergie a été rayonnée en ondes gravitationnelles&nbsp;? Donne le résultat en unités de 10⁴⁷ J, arrondi au dixième.',lab:'E =',unit:'× 10⁴⁷ J',ans:5.37,tol:.05,hint:'Masse perdue : 36 + 29 − 62 = 3 M☉, puis <i>E</i> = <i>Δm c</i>².',why:'E = 3 × 1,99·10³⁰ × 9·10¹⁶ = 5,37·10⁴⁷ J.'},
   {q:'e) À combien de soleils cette puissance moyenne pendant 0,20 s équivaut-elle&nbsp;? Donne le résultat en unités de 10²¹ soleils, arrondi au dixième.',lab:'N =',unit:'× 10²¹',ans:7.07,tol:.1,hint:'<i>P</i> = <i>E</i>/0,20 s, puis divise par 3,8·10²⁶ W.',why:'P = 5,37·10⁴⁷/0,20 = 2,69·10⁴⁸ W, soit 2,69·10⁴⁸/3,8·10²⁶ ≈ 7,1·10²¹ soleils : davantage que toutes les étoiles de l’Univers observable.'},
  ],
  sol:'<p>L’amplitude <i>h</i> = 10⁻²¹ produit sur chaque bras de 4 km une variation ½<i>hL</i> = 2·10⁻¹⁸ m, de signes opposés : l’interféromètre voit 4·10⁻¹⁸ m, quatre attomètres.</p><p>À 150 Hz, l’orbite a une fréquence de 75 Hz. Kepler donne <i>r</i> = (<i>GM</i>/<i>ω</i>²)^(1/3) ≈ 340 km pour 65 M☉, soit 1,8 fois le rayon de Schwarzschild de la masse totale (192 km) : les deux corps sont à la limite de se toucher, et seuls des trous noirs tiennent dans un si petit volume. C’est ainsi que la nature des sources a été établie.</p><p>Le bilan de masse donne 3 M☉ rayonnées, <i>E</i> = 5,4·10⁴⁷ J. Étalée sur 0,2 s, la puissance atteint 2,7·10⁴⁸ W, environ 7·10²¹ fois celle du Soleil. Rien de cette énergie n’est passé par la lumière : elle est entièrement dans la déformation de l’espace-temps, qui ne vaut plus que 10⁻²¹ après 1,3 milliard d’années-lumière de voyage.</p>'},
 {kind:'Problème',h:'Une galaxie à z = 0,050',
  p:'Dans le spectre d’une galaxie, toutes les raies sont décalées de <i>z</i> = 0,050. On prend <i>H</i>₀ = 70 km/s/Mpc, <i>c</i> = 3,00·10⁵ km/s = 3,00·10⁸ m/s, 1 Mpc = 3,09·10²² m, 1 an = 3,156·10⁷ s. On cherche où est cette galaxie, quand sa lumière est partie, et ce que l’incertitude sur <i>H</i>₀ change.',
  parts:[
   {q:'a) À quelle longueur d’onde observe-t-on la raie Hα, émise à 656,3 nm&nbsp;? Arrondis au dixième de nanomètre.',lab:'λ =',unit:'nm',ans:689.1,tol:.1,hint:'<i>λ</i><sub>obs</sub> = (1 + <i>z</i>) <i>λ</i><sub>e</sub>.',why:'λ<sub>obs</sub> = 1,050 × 656,3 ≈ 689,1 nm.'},
   {q:'b) Quelle est la distance de la galaxie&nbsp;? Arrondis au mégaparsec.',lab:'d =',unit:'Mpc',ans:214.3,tol:1,hint:'<i>v</i> ≈ <i>cz</i>, puis <i>d</i> = <i>v</i>/<i>H</i>₀.',why:'v = 3,00·10⁵ × 0,050 = 15 000 km/s, d = 15 000/70 ≈ 214 Mpc.'},
   {q:'c) Combien de temps la lumière a-t-elle voyagé, en millions d’années (en négligeant l’expansion pendant le trajet)&nbsp;? Arrondis à 10 millions d’années.',lab:'t =',unit:'millions d’années',ans:699,tol:12,hint:'Convertis <i>d</i> en mètres, divise par <i>c</i>, puis par le nombre de secondes dans une année.',why:'d = 214,3 × 3,09·10²² = 6,62·10²⁴ m. t = 6,62·10²⁴/3·10⁸ = 2,21·10¹⁶ s = 2,21·10¹⁶/3,156·10⁷ ≈ 7,0·10⁸ ans : 700 millions d’années.'},
   {q:'d) Pendant ce trajet, l’Univers…',opts:['n’a pas changé : seule la galaxie a bougé','s’est étiré de 5,0 % : toutes les distances entre galaxies indépendantes ont été multipliées par 1,050, comme la longueur d’onde','s’est étiré de 5,0 %, y compris les atomes du télescope, ce qui compense exactement l’effet','s’est contracté, puisque la galaxie s’est rapprochée de la position où on la voit'],ans:1,hint:'Que mesure 1 + <i>z</i> en cosmologie&nbsp;?',why:'1 + z est le facteur d’étirement de l’Univers entre émission et réception : 1,050. La longueur d’onde a été étirée avec l’espace ; les atomes et les systèmes liés, eux, gardent leur taille.'},
   {q:'e) Avec <i>H</i>₀ = 73 km/s/Mpc au lieu de 70, le temps de Hubble 1/<i>H</i>₀ vaut, en milliards d’années (arrondi au dixième)…',lab:'1/H₀ =',unit:'milliards d’années',ans:13.4,tol:.1,hint:'<i>H</i>₀ en s⁻¹ : 7,3·10⁴/3,09·10²² ; puis inverse et convertis en années.',why:'H₀ = 7,3·10⁴/3,09·10²² = 2,36·10⁻¹⁸ s⁻¹, 1/H₀ = 4,23·10¹⁷ s = 13,4 milliards d’années, contre 14,0 avec 70 km/s/Mpc. Trois pour cent sur H₀, trois pour cent sur l’âge.'},
  ],
  sol:'<p>Un décalage <i>z</i> = 0,050 étire chaque longueur d’onde d’un facteur 1,050 : Hα passe de 656,3 à 689,1 nm. Comme <i>z</i> est petit, <i>v</i> ≈ <i>cz</i> = 15 000 km/s et la loi de Hubble–Lemaître donne <i>d</i> = <i>v</i>/<i>H</i>₀ ≈ 214 Mpc = 6,6·10²⁴ m.</p><p>La lumière a mis <i>d</i>/<i>c</i> ≈ 2,2·10¹⁶ s ≈ 700 millions d’années pour nous parvenir ; pendant ce temps, l’Univers s’est dilaté de 5 %, et c’est cette dilatation que la longueur d’onde enregistre. La galaxie n’a pas « couru » : l’espace entre elle et nous a grandi.</p><p>L’âge estimé 1/<i>H</i>₀ dépend directement de <i>H</i>₀ : 14,0 milliards d’années pour 70, 13,4 pour 73, 14,6 pour 67. La valeur précise de <i>H</i>₀ reste l’un des problèmes ouverts de la cosmologie.</p>'},
]},
);
})();
